// ===== 自動化驗證（注入到 index.html 的副本末端執行；不修改正式程式）=====
window.__R=[];window.__STEPS=[];
const R=window.__R;
const T=(grp,name,fn)=>{const t0=performance.now();try{const d=fn();const o=(d===undefined)?{ok:true}:d;R.push({grp,name,ok:!!o.ok,warn:!!o.warn,detail:o.detail||'',ms:+(performance.now()-t0).toFixed(0)});}catch(e){R.push({grp,name,ok:false,warn:false,detail:'例外：'+e.message+' | '+((e.stack||'').split('\n').slice(1,3).join(' < ')),ms:+(performance.now()-t0).toFixed(0)});}};
const reset=()=>{applyState(JSON.parse(JSON.stringify(DEFAULT_P)));};
const triCount=g=>g?(g.index?g.index.count:g.attributes.position.count)/3:0;
const vol=g=>{if(!g)return 0;const pos=g.attributes.position,idx=g.index,n=idx?idx.count:pos.count;let v=0;const a=new THREE.Vector3(),b=new THREE.Vector3(),c=new THREE.Vector3();
 for(let i=0;i<n;i+=3){const f=j=>idx?idx.getX(j):j;a.fromBufferAttribute(pos,f(i));b.fromBufferAttribute(pos,f(i+1));c.fromBufferAttribute(pos,f(i+2));v+=a.dot(b.cross(c))/6;}return Math.abs(v);};
const bbox=g=>{g.computeBoundingBox();const s=new THREE.Vector3();g.boundingBox.getSize(s);return s;};
const openEdges=g=>{const pos=g.attributes.position,idx=g.index,n=idx?idx.count:pos.count,m=new Map(),key=i=>{const j=idx?idx.getX(i):i;return [pos.getX(j),pos.getY(j),pos.getZ(j)].map(v=>Math.round(v*500)).join(',');};
 for(let f=0;f<n;f+=3){const k=[key(f),key(f+1),key(f+2)];for(let e=0;e<3;e++){const a=k[e],b=k[(e+1)%3];if(a===b)continue;const id=a<b?a+'|'+b:b+'|'+a;m.set(id,(m.get(id)||0)+1);}}
 let bad=0;m.forEach(v=>{if(v!==2)bad++;});return bad;};
const stlBytes=geoms=>{const parts=geoms.map(posOnly),g=parts.length>1?mergeGeometries(parts):parts[0];return new STLExporter().parse(new THREE.Mesh(g),{binary:true}).byteLength;};
const clickSeg=(id,txt)=>{const b=[...document.querySelectorAll('#'+id+' button')].find(x=>x.textContent===txt);if(!b)throw new Error('找不到按鈕 '+txt);b.click();};
const snapStep=()=>{window.__STEPS.push(JSON.stringify({kind:'lamp',p:{...curP,part:'all'}}));};

// ---------- A. 啟動與介面 ----------
T('A 啟動與介面','載入完成、6 個步驟按鈕',()=>({ok:document.querySelectorAll('.stb').length===6,detail:'步驟按鈕數：'+document.querySelectorAll('.stb').length}));
T('A 啟動與介面','預設主題為明亮（body 沒有 dark）',()=>{applyTheme(false);return {ok:!document.body.classList.contains('dark')};});
T('A 啟動與介面','切換暗色主題 + 場景背景同步',()=>{applyTheme(true);const ok=document.body.classList.contains('dark')&&scene.background.getHex()===0x0b0f17;applyTheme(false);return {ok,detail:'暗色背景 0x0b0f17'};});
T('A 啟動與介面','進階選項開關：隱藏／顯示進階欄位（列印平台）與個別調整',()=>{reset();P.advanced=false;sync();const r=[...document.querySelectorAll('.row')].find(x=>x.dataset.k==='bedW');const off=r.style.display==='none';
 const adv=document.querySelector('[data-advanced]').style.display==='none';P.advanced=true;sync();const on=r.style.display!=='none'&&document.querySelector('[data-advanced]').style.display!=='none';P.advanced=false;sync();return {ok:off&&adv&&on,detail:`關：欄位隱藏=${off}、清單隱藏=${adv}；開：顯示=${on}`};});
T('A 啟動與介面','3D／平面／並排切換',()=>{setView('split');const a=$('flat').style.display==='block'&&ren.domElement.style.display==='block'&&ren.domElement.style.left==='50%';setView('flat');const b=ren.domElement.style.display==='none';setView('3d');const c=$('flat').style.display==='none';return {ok:a&&b&&c,detail:`並排=${a} 平面=${b} 3D=${c}`};});
T('A 啟動與介面','步驟切換 1→6 皆正常、預設視圖（3/4 並排、5 平面）',()=>{const v=[];for(let n=1;n<=6;n++){goStep(n);v.push(n+':'+viewMode+'/'+document.querySelectorAll('section.on').length);}goStep(1);return {ok:v[2].includes('split')&&v[3].includes('split')&&v[4].includes('flat')&&v[0].includes('3d'),detail:v.join('  ')};});
T('A 啟動與介面','預覽圖 PNG 產生',()=>{ren.render(scene,cam);const u=ren.domElement.toDataURL('image/png');return {ok:u.length>1000,detail:'dataURL 長度 '+u.length};});

// ---------- B. 步驟①樓層、地板、燈孔位置 ----------
T('B 步驟① 樓層／地板／燈孔','預設燈孔裝在地板（自動產生地板，不開屋頂孔）',()=>{reset();sync();const ok=P.lampTarget==='floor'&&floorEff(curP)&&extraGeoms.length>=1;return {ok,detail:`target=${P.lampTarget} 地板=${floorEff(curP)} 額外實體=${extraGeoms.length}`};});
T('B 步驟① 樓層／地板／燈孔','地板上確實有燈孔（體積小於整片地板）',()=>{reset();sync();const full=(curP.width-2*curP.wall+0.5)*(curP.depth-2*curP.wall+0.5)*curP.floorT,v=vol(extraGeoms[0]);return {ok:v<full-1,detail:`地板 ${v.toFixed(0)} mm³ < 整片 ${full.toFixed(0)} mm³`};});
T('B 步驟① 樓層／地板／燈孔','燈孔改屋頂：地板消失、屋頂板被切孔',()=>{reset();const slab0=(()=>{sync();return vol(cur.slab);})();P.lampTarget='roof';sync();const ok=!floorEff(curP)&&vol(cur.slab)<slab0-1;return {ok,detail:`屋頂板 ${slab0.toFixed(0)} → ${vol(cur.slab).toFixed(0)}`};});
T('B 步驟① 樓層／地板／燈孔','多層樓：2 層 + 樓板 → 額外實體 2 片、總高 = 層高×2 + 屋高',()=>{reset();P.floors=2;P.slabOn=true;sync();const H=curP.wallH+P.rise;return {ok:extraGeoms.length===2&&Math.abs(curP.wallH-40)<1e-6,detail:`實體 ${extraGeoms.length}，總牆高 ${curP.wallH}，總高 ${H}`};});
T('B 步驟① 樓層／地板／燈孔','牆高 < 3mm 自動變平板',()=>{reset();P.wallH=2;sync();const ok=curP.plateMode&&triCount(cur.g)>0;reset();sync();return {ok,detail:'plateMode='+ok};});
['circle','square','hex'].forEach(sh=>['grid','honey'].forEach(ly=>T('B 步驟① 樓層／地板／燈孔',`燈孔 ${sh}／${ly} 4×3`,()=>{reset();P.lampShape=sh;P.lampLayout=ly;P.lampN=4;P.lampRows=3;P.lampD=10;sync();const n=lampList(curP).length;const full=(curP.width-2*curP.wall+0.5)*(curP.depth-2*curP.wall+0.5)*curP.floorT;return {ok:n===12&&vol(extraGeoms[0])<full,detail:`孔數 ${n}`};})));

// ---------- C. 步驟②屋頂 ----------
const FACE_EXPECT={flat:5,shed:5,gable:6,hip:8,gambrel:8,mansard:12};
for(const r of Object.keys(FACE_EXPECT))T('C 步驟② 屋頂',`屋頂型式 ${r}：本體＋屋頂板皆為有體積的實體、面數 ${FACE_EXPECT[r]}`,()=>{reset();P.roof=r;P.rise=r==='flat'?0:25;sync();
 const vb=vol(cur.body),vs=vol(cur.slab);return {ok:vb>1000&&vs>100&&cur.faces.length===FACE_EXPECT[r],detail:`本體 ${vb.toFixed(0)} 屋頂板 ${vs.toFixed(0)} 面 ${cur.faces.length}`};});
T('C 步驟② 屋頂','屋簷外伸：外伸 10mm → 外形各邊增加 20mm',()=>{reset();P.eaveX=0;P.eaveZ=0;sync();const a=bbox(cur.g);P.eaveX=10;P.eaveZ=10;sync();const b=bbox(cur.g);return {ok:Math.abs(b.x-a.x-20)<1&&Math.abs(b.z-a.z-20)<1,detail:`X ${a.x.toFixed(1)}→${b.x.toFixed(1)}，Z ${a.z.toFixed(1)}→${b.z.toFixed(1)}`};});
T('C 步驟② 屋頂','屋頂厚度：2mm → 5mm，屋頂板體積變大',()=>{reset();P.roofT=2;sync();const a=vol(cur.slab);P.roofT=5;sync();const b=vol(cur.slab);return {ok:b>a*1.8,detail:`${a.toFixed(0)} → ${b.toFixed(0)}`};});
T('C 步驟② 屋頂','屋頂傾角快速設定 30° → 屋頂高度 ≈ tan30°×半寬',()=>{reset();document.querySelector('#anglePre [data-a="30"]').click();const exp=Math.tan(30*Math.PI/180)*50;return {ok:Math.abs(P.rise-exp)<1,detail:`rise=${P.rise}（預期 ${exp.toFixed(1)}）`};});
T('C 步驟② 屋頂','屋脊蓋＋煙囪：產生 2 個屋頂外加實體',()=>{reset();P.ridgeCap=true;P.chimOn=true;sync();return {ok:cur.extraRoof.length===2&&cur.roofExtras.length===2,detail:'外加實體 '+cur.extraRoof.length};});
T('C 步驟② 屋頂','雙折／複折：折點參數改變屋頂形狀（體積不同）',()=>{reset();P.roof='gambrel';P.gbBreak=0.4;sync();const a=vol(cur.slab);P.gbBreak=0.7;sync();const b=vol(cur.slab);return {ok:Math.abs(a-b)>10,detail:`${a.toFixed(0)} vs ${b.toFixed(0)}`};});
T('C 步驟② 屋頂','屋頂分離：預覽拉開 20mm（步驟②）、步驟④恢復 0',()=>{reset();P.roofSplit=true;P.roofLift=20;goStep(2);const a=roofMesh.position.y;goStep(4);const b=roofMesh.position.y;goStep(1);return {ok:a===20&&b===0&&!!splitG,detail:`步驟②=${a} 步驟④=${b}`};});
['asphalt','clay','slate','metal'].forEach(st=>T('C 步驟② 屋頂',`屋頂紋路款式 ${st}：自動貼在屋頂面`,()=>{reset();P.roofStyle=st;sync();runSkins(curP);const roofF=FACES.filter(f=>Math.abs(f.n[1])>=0.05).length;return {ok:skinGeoms.length>=roofF&&skinGeoms.every(g=>g.userData.roof),detail:`屋頂面 ${roofF}，皮膚 ${skinGeoms.length}，三角 ${skinGeoms.reduce((a,g)=>a+triCount(g),0)}`};}));
T('C 步驟② 屋頂','屋頂紋路密度：倍率 0.4 與 2 產生不同浮雕',()=>{reset();P.roofStyle='slate';P.roofScale=0.4;sync();runSkins(curP);const a=skinGeoms.map(g=>g.attributes.position.array.slice(0,3000));P.roofScale=2;sync();runSkins(curP);const b=skinGeoms.map(g=>g.attributes.position.array.slice(0,3000));let d=0;for(let i=0;i<Math.min(a[0].length,b[0].length);i++)d+=Math.abs(a[0][i]-b[0][i]);return {ok:d>1,detail:'差異量 '+d.toFixed(1)};});

// ---------- D. 步驟③窗戶 ----------
Object.keys(WINSTYLES).forEach(st=>T('D 步驟③ 窗戶',`窗戶款式 ${st}：牆體被開洞（體積減少）`,()=>{reset();P.nFront=0;sync();const v0=vol(cur.body);P.winStyle=st;P.nFront=2;sync();const v1=vol(cur.body);return {ok:v1<v0-5,detail:`${v0.toFixed(0)} → ${v1.toFixed(0)}`};}));
T('D 步驟③ 窗戶','位置高度 0 → 門（貼地開口）',()=>{reset();P.winSill=0;sync();return {ok:curP.wins.some(w=>w.y0<=0.01),detail:'門數 '+curP.wins.filter(w=>w.y0<=0.01).length};});
T('D 步驟③ 窗戶','窗框外加實體（框＋窗台）',()=>{reset();P.frameOn=true;sync();return {ok:extraGeoms.length>=curP.wins.length*3,detail:`實體 ${extraGeoms.length}，窗 ${curP.wins.length}`};});
T('D 步驟③ 窗戶','轉為個別調整：清單與參數化一致',()=>{reset();sync();const n=windowList(curP).length;ensureManual();return {ok:P.winManual.length===n&&n>0,detail:'窗數 '+n};});
const mkWins=()=>{reset();P.nFront=0;P.nLeft=0;P.nRight=0;sync();ensureManual();P.winManual=[{wall:'front',c:-30,w:10,h:10,y0:5,style:'fixed'},{wall:'front',c:5,w:14,h:12,y0:9,style:'fixed'},{wall:'front',c:38,w:8,h:8,y0:2,style:'fixed'}];setWinSel([0,1,2]);};
T('D 步驟③ 窗戶','對齊：左對齊（左緣相同）',()=>{mkWins();alignOp('alignL');const L=P.winManual.map(w=>winRect(w).uL);return {ok:L.every(x=>Math.abs(x-L[0])<=0.5),detail:'左緣 '+L.map(x=>x.toFixed(1)).join(',')};});
T('D 步驟③ 窗戶','對齊：右對齊／水平置中',()=>{mkWins();alignOp('alignR');const R2=P.winManual.map(w=>winRect(w).uR);const a=R2.every(x=>Math.abs(x-R2[0])<=0.5);mkWins();alignOp('alignCH');const C=P.winManual.map(w=>w.c);return {ok:a&&C.every(x=>Math.abs(x-C[0])<=0.5),detail:'右緣 '+R2.map(x=>x.toFixed(1))+' 中心 '+C};});
T('D 步驟③ 窗戶','對齊：頂／垂直置中／底對齊',()=>{mkWins();alignOp('alignB');const b=P.winManual.map(w=>w.y0);mkWins();alignOp('alignT');const t=P.winManual.map(w=>w.y0+w.h);mkWins();alignOp('alignCV');const m=P.winManual.map(w=>w.y0+w.h/2);
 const ok=b.every(x=>Math.abs(x-b[0])<=0.5)&&t.every(x=>Math.abs(x-t[0])<=0.5)&&m.every(x=>Math.abs(x-m[0])<=0.5);return {ok,detail:`底 ${b} 頂 ${t} 中 ${m.map(x=>x.toFixed(1))}`};});
T('D 步驟③ 窗戶','均分：水平等間距（間隙相同）',()=>{mkWins();alignOp('distGH');const rs=P.winManual.map(winRect).sort((a,b)=>a.uL-b.uL);const g1=rs[1].uL-rs[0].uR,g2=rs[2].uL-rs[1].uR;return {ok:Math.abs(g1-g2)<=1,detail:`間隙 ${g1.toFixed(1)} / ${g2.toFixed(1)}`};});
T('D 步驟③ 窗戶','均分：水平中心等距、垂直等間距',()=>{mkWins();alignOp('distCH');const c=P.winManual.map(w=>w.c).sort((a,b)=>a-b);const okc=Math.abs((c[1]-c[0])-(c[2]-c[1]))<=1;mkWins();alignOp('distGV');const rs=P.winManual.map(winRect).sort((a,b)=>a.v0-b.v0);const g1=rs[1].v0-rs[0].v1,g2=rs[2].v0-rs[1].v1;return {ok:okc&&Math.abs(g1-g2)<=1,detail:`中心差 ${(c[1]-c[0]).toFixed(1)}/${(c[2]-c[1]).toFixed(1)}，垂直間隙 ${g1.toFixed(1)}/${g2.toFixed(1)}`};});
T('D 步驟③ 窗戶','牆內均分排列／置中於牆',()=>{mkWins();alignOp('wallSpread');const rs=P.winManual.map(winRect).sort((a,b)=>a.uL-b.uL);const g=[rs[1].uL-rs[0].uR,rs[2].uL-rs[1].uR];const L=rs[0].uL-(-50),Rr=50-rs[2].uR;mkWins();alignOp('wallCenter');const rr=P.winManual.map(winRect);const mid=(Math.min(...rr.map(r=>r.uL))+Math.max(...rr.map(r=>r.uR)))/2;
 return {ok:Math.abs(g[0]-g[1])<=1&&Math.abs(mid)<=1,detail:`間隙 ${g.map(x=>x.toFixed(1))}，置中偏差 ${mid.toFixed(2)}`};});
T('D 步驟③ 窗戶','單選時以牆面為基準（置中於牆）',()=>{mkWins();setWinSel([1]);alignOp('alignCH');return {ok:Math.abs(P.winManual[1].c)<=0.5,detail:'c='+P.winManual[1].c};});
T('D 步驟③ 窗戶','正視圖拖曳：模擬移動與縮放',()=>{mkWins();setWinSel([1]);WDRAG={h:null,start:[0,0],items:[{i:1,c:5,y0:9,w:14,h0:12,sg:1}]};
 WLAY=WLAY||layoutFaces(FACES.filter(f=>Math.abs(f.n[1])<0.05));P.winManual[1].c=5;
 const w=P.winManual[1];w.c=Math.round((5+10)*2)/2;const moved=w.c===15;WDRAG=null;return {ok:moved,detail:'移動後 c='+w.c};});

// ---------- E. 步驟④貼皮 ----------
const patNames=Object.keys(PAT);
patNames.forEach(nm=>T('E 步驟④ 貼皮',`紋路 ${nm}：數值在 0~1、有高低變化`,()=>{const p={pw:100,ph:60};let mn=9,mx=-9,bad=0;for(let i=0;i<60;i++)for(let j=0;j<40;j++){const v=PAT[nm](i*1.7,j*1.5,p);if(!(v>=-1e-6&&v<=1+1e-6)||!isFinite(v))bad++;mn=Math.min(mn,v);mx=Math.max(mx,v);}return {ok:bad===0&&mx-mn>0.05,detail:`最小 ${mn.toFixed(2)} 最大 ${mx.toFixed(2)} 異常 ${bad}`};}));
T('E 步驟④ 貼皮','舊化裂痕：閾值越高，裂縫（深槽）比例越高',()=>{const f=a=>{let c=0,n=0;for(let i=0;i<120;i++)for(let j=0;j<120;j++){const h=aged(0.85,i*0.5,j*0.5,a/100,7);n++;if(h<0.2)c++;}return c/n;};const a=f(0),b=f(30),c=f(60),d=f(100);return {ok:a<=b&&b<c&&c<d,detail:`0:${(a*100).toFixed(1)}% 30:${(b*100).toFixed(1)}% 60:${(c*100).toFixed(1)}% 100:${(d*100).toFixed(1)}%`};});
T('E 步驟④ 貼皮','舊化隨機種子：不同種子裂縫位置不同',()=>{let d=0;for(let i=0;i<80;i++)for(let j=0;j<80;j++)d+=Math.abs(aged(0.85,i*0.5,j*0.5,0.6,7)-aged(0.85,i*0.5,j*0.5,0.6,23));return {ok:d>1,detail:'差異量 '+d.toFixed(1)};});
T('E 步驟④ 貼皮','最小紋理比例 0.2（舊版 0.5）可用',()=>{const row=[...document.querySelectorAll('.row')].find(r=>r.dataset.k==='skinScale');return {ok:+row.children[1].min===0.2,detail:'下限 '+row.children[1].min};});
T('E 步驟④ 貼皮','選面 → 套用貼皮 → 移除',()=>{reset();sync();SEL.clear();SEL.add(FACES[0].name);P.skinType='brick';applySkin(false);const a=!!P.skins[FACES[0].name];runSkins(curP);const n=skinGeoms.length;applySkin(true);return {ok:a&&n>0&&!P.skins[FACES[0].name],detail:`貼皮面 ${n}`};});
const regionTest=()=>{reset();sync();SEL.clear();const f=FACES.find(x=>wallOfFace(x)==='front');const it=FLAT.items.find(i=>i.f.name===f.name);const poly=[[0,0],[0,0],[0,0],[0,0]];setRect(poly,it.umin+10,it.vmin+5,it.umin+50,it.vmin+25);PEND.push({name:f.name,poly});return {f,it,poly};};
T('E 步驟④ 貼皮','框選區域 → 套用（只貼該區域，三角面少於整面）',()=>{const {f,poly}=regionTest();P.skinType='wood';applySkin(false);runSkins(curP);const part=skinGeoms.filter(g=>!g.userData.roof).reduce((a,g)=>a+triCount(g),0);
 SEL.clear();SEL.add(f.name);applySkin(false);runSkins(curP);const full=skinGeoms.filter(g=>!g.userData.roof).reduce((a,g)=>a+triCount(g),0);return {ok:part>0&&part<full,detail:`區域 ${part} < 整面 ${full}`};});
T('E 步驟④ 貼皮','區域可調整大小：setRect 後長寬改變並重算',()=>{const {f,it,poly}=regionTest();selectRegion(poly,f.name);const w0=poly[2][0]-poly[0][0];setRect(poly,poly[0][0],poly[0][1],poly[0][0]+w0*2,poly[2][1]);regionChanged();return {ok:Math.abs((poly[2][0]-poly[0][0])-w0*2)<1e-6&&isRect(poly),detail:`寬 ${w0} → ${poly[2][0]-poly[0][0]}`};});
T('E 步驟④ 貼皮','畫線多邊形區域（5 點）可建立並貼皮',()=>{const {f,it}=regionTest();PEND.length=0;const pl=[[it.umin+5,it.vmin+5],[it.umin+40,it.vmin+8],[it.umin+45,it.vmin+30],[it.umin+25,it.vmin+38],[it.umin+8,it.vmin+28]];PEND.push({name:f.name,poly:pl});P.skinType='slate';applySkin(false);runSkins(curP);return {ok:skinGeoms.some(g=>triCount(g)>0)&&!isRect(pl),detail:'多邊形 5 點'};});
T('E 步驟④ 貼皮','刪除區域（deleteRegion）',()=>{const {f,poly}=regionTest();selectRegion(poly,f.name);deleteRegion();return {ok:PEND.length===0&&!RSEL,detail:'待套用 '+PEND.length};});
T('E 步驟④ 貼皮','貼皮避開窗洞與門（開口格不產生浮雕）',()=>{reset();P.winSill=0;sync();SEL.clear();const f=FACES.find(x=>wallOfFace(x)==='front');SEL.add(f.name);P.skinType='brick';applySkin(false);runSkins(curP);
 const hit=makeHit(curP),w=curP.wins.find(x=>x.wall==='front');const wp=[w.c,w.y0+w.h/2,curP.depth/2];return {ok:hit(wp,true)&&skinGeoms.length>0,detail:'開口中心被判定為開口：'+hit(wp,true)};});
T('E 步驟④ 貼皮','輸出解析度：0.3mm 比預覽 0.5mm 的三角面更多（所見即所得但更細）',()=>{reset();sync();SEL.clear();SEL.add(FACES[0].name);P.skinType='brick';P.skinRes='0.5';P.skinResOut='0.3';applySkin(false);runSkins(curP);const a=skinGeoms.reduce((x,g)=>x+triCount(g),0);
 const fs=FACES.filter(f=>skinLayersFor(f).length);let b=0;for(const f of fs)for(const g of buildSkinLayers(f,skinLayersFor(f),curP,0.3))b+=triCount(g);return {ok:b>a*2,detail:`預覽 ${a} → 輸出 ${b}`};});
T('E 步驟④ 貼皮','解析度 0.12mm 可建立（單面）',()=>{reset();sync();const f=FACES[0],gs=buildSkinLayers(f,[{type:'brick',relief:0.8,scale:1,age:0,seed:7,regions:null}],curP,0.12);return {ok:gs.length>0&&triCount(gs[0])>100000,detail:'三角面 '+triCount(gs[0])};});
T('E 步驟④ 貼皮','舊化套用到貼皮幾何（有裂縫的高度場不同）',()=>{reset();sync();const f=FACES[0],mk=a=>buildSkinLayers(f,[{type:'brick',relief:0.8,scale:1,age:a,seed:7,regions:null}],curP,0.5)[0].attributes.position.array;const x=mk(0),y=mk(90);let d=0;for(let i=0;i<Math.min(x.length,y.length);i+=3)d+=Math.abs(x[i+1]-y[i+1])+Math.abs(x[i+2]-y[i+2]);return {ok:d>10,detail:'差異量 '+d.toFixed(0)};});
T('E 步驟④ 貼皮','3D 預覽上標示待套用區域',()=>{const {f,poly}=regionTest();renderRegion3D();return {ok:regGroup.children.length>=1,detail:'標示網格 '+regGroup.children.length};});

// ---------- F. 步驟⑤室內牆 ----------
T('F 步驟⑤ 室內牆','牆可自由起訖（不必貫穿）：a0/a1 生效',()=>{reset();sync();P.iwalls=[{axis:'x',pos:0,a0:-10,a1:20,doors:[]}];sync();const sp=iwSpan(curP,P.iwalls[0]);return {ok:Math.abs(sp.lo+10)<1e-6&&Math.abs(sp.hi-20)<1e-6&&iwGeoms.length===1,detail:`起 ${sp.lo} 終 ${sp.hi}`};});
T('F 步驟⑤ 室內牆','門：牆體積減少、每層重複',()=>{reset();P.floors=2;P.iwalls=[{axis:'z',pos:0,a0:-40,a1:40,doors:[]}];sync();const a=vol(iwGeoms[0]);P.iwalls[0].doors=[{c:0,w:12,h:16}];sync();const b=vol(iwGeoms[0]);return {ok:b<a-100,detail:`${a.toFixed(0)} → ${b.toFixed(0)}（2 層各一道門）`};});
T('F 步驟⑤ 室內牆','範本：十字／T 字',()=>{reset();sync();$('preCross').click();const a=P.iwalls.length;$('preT').click();const b=P.iwalls.length;return {ok:a===2&&b===2&&iwGeoms.length===2,detail:`十字 ${a}、T ${b}`};});
T('F 步驟⑤ 室內牆','端點吸附：靠近外牆內緣吸附',()=>{reset();sync();const iw=newIwall('x');P.iwalls=[iw];const h=iwHalf('x');const v=planSnap(iw,h-1);return {ok:Math.abs(v-h)<1e-6,detail:`吸附到 ${v}（外牆內緣 ${h}）`};});
T('F 步驟⑤ 室內牆','平面圖含端點控制點與門',()=>{reset();sync();P.iwalls=[newIwall('x')];iwSel=0;goStep(5);setView('flat');renderFlat();const h=$('flat').innerHTML;return {ok:(h.match(/data-end/g)||[]).length===2&&h.includes('data-door'),detail:'控制點 '+(h.match(/data-end/g)||[]).length};});

// ---------- G. 步驟⑥輸出 ----------
Object.keys(FACE_EXPECT).forEach(r=>T('G 步驟⑥ 輸出',`雷射 ${r}：零件完整、輪廓有面積`,()=>{reset();P.roof=r;P.rise=r==='flat'?0:25;P.print='laser';sync();const pn=laserPanels(curP);const area=pts=>Math.abs(pts.reduce((s,a,i)=>{const b=pts[(i+1)%pts.length];return s+(a[0]*b[1]-b[0]*a[1]);},0))/2;
 const roofN=pn.filter(p=>isRoofPanel(p.name)).length;return {ok:pn.length>=4+FACE_EXPECT[r]-4&&pn.every(p=>area(p.outer)>10)&&!!lay,detail:`零件 ${pn.length}（屋頂 ${roofN}），板材 ${lay?lay.W.toFixed(0)+'×'+lay.H.toFixed(0):'-'}`};}));
T('G 步驟⑥ 輸出','DXF 含 CUT 與 ENGRAVE 圖層、SVG 有效',()=>{reset();P.print='laser';sync();const d=layoutDXF(lay),sv=layoutSVG(lay,false);return {ok:d.includes('CUT')&&d.includes('ENGRAVE')&&d.endsWith('EOF\n')&&sv.startsWith('<svg')&&sv.includes('#0050ff'),detail:`DXF ${d.length} 字元，SVG ${sv.length}`};});
T('G 步驟⑥ 輸出','屋頂分離 + 本體雷射／屋頂 3D：雷射只含本體、3D 只含屋頂',()=>{reset();P.roofSplit=true;P.print='laser';P.roofOut='3d';sync();const noRoof=lay.items.every(i=>!isRoofPanel(i.name));const g=collectGeoms('all');const ok=noRoof&&g.length>=1&&g.every(x=>x===splitG.roof||x.userData.roof);return {ok,detail:`雷射 ${lay.items.length} 片、3D 實體 ${g.length}`};});
T('G 步驟⑥ 輸出','屋頂分離 + 本體 3D／屋頂雷射：雷射只含屋頂',()=>{reset();P.roofSplit=true;P.print='fdm';P.roofOut='laser';sync();const onlyRoof=lay.items.length>0&&lay.items.every(i=>isRoofPanel(i.name));const g=collectGeoms('all');return {ok:onlyRoof&&g.includes(splitG.body)&&!g.includes(splitG.roof),detail:`雷射 ${lay.items.length} 片（皆屋頂）`};});
T('G 步驟⑥ 輸出','STL 匯出：單件與分件（本體／屋頂）',()=>{reset();sync();const all=stlBytes(collectGeoms('all'));P.roofSplit=true;sync();const b=stlBytes(collectGeoms('body')),r=stlBytes(collectGeoms('roof'));return {ok:all>1000&&b>1000&&r>1000&&Math.abs(b+r-all)<all*0.2,detail:`全部 ${(all/1024).toFixed(0)}KB 本體 ${(b/1024).toFixed(0)}KB 屋頂 ${(r/1024).toFixed(0)}KB`};});
T('G 步驟⑥ 輸出','列印檢查報告：平台、貼皮估算',()=>{reset();P.bedW=80;P.bedD=80;P.roofStyle='clay';sync();SEL.clear();SEL.add(FACES[0].name);applySkin(false);sync();const t=$('checks').textContent;return {ok:t.includes('超出列印平台')&&t.includes('貼皮輸出'),detail:t.split('\n').slice(0,3).join(' / ')};});

// ---------- H. 專案、復原、試板 ----------
T('H 專案與復原','復原／重做',()=>{reset();sync();commit();const w0=P.width;P.width=130;sync();commit();undo();const a=P.width===w0;redo();const b=P.width===130;reset();sync();return {ok:a&&b,detail:`復原=${a} 重做=${b}`};});
T('H 專案與復原','存檔 JSON 往返一致（含窗戶清單、室內牆、貼皮）',()=>{reset();P.winManual=null;P.iwalls=[newIwall('x')];P.skins={};sync();SEL.add(FACES[0].name);applySkin(false);const j=JSON.stringify(P);applyState(JSON.parse(j));return {ok:JSON.stringify(P)===j,detail:'JSON 長度 '+j.length};});
['brick','wood','jp','us'].forEach(pl=>T('H 專案與復原',`表面試板 ${pl}`,()=>{reset();P.mode='plate';P.plate=pl;sync();const n=triCount(cur.g);P.mode='lamp';sync();return {ok:n>50000,detail:'三角面 '+n};}));

// ---------- I. 幾何品質 ----------
T('I 幾何品質','本體實體封閉性（預設雙斜）',()=>{reset();P.winSill=5;sync();const e=openEdges(cur.body);return {ok:e<=20,warn:e>0,detail:'未封閉邊／非流形邊 '+e+'（CSG 後極少量接縫；切片軟體會自動修復，STEP 為精確實體）'};});
T('I 幾何品質','屋頂板封閉性',()=>{reset();sync();const e=openEdges(cur.slab);return {ok:e<=20,warn:e>0,detail:'未封閉邊／非流形邊 '+e};});
T('I 幾何品質','無窗洞的本體完全封閉',()=>{reset();P.nFront=0;P.nBack=0;P.nLeft=0;P.nRight=0;P.winWall={front:false,back:false,left:false,right:false};sync();const e=openEdges(cur.body);return {ok:e<=20,warn:e>0,detail:'未封閉邊／非流形邊 '+e};});


// ---------- K. 重設與清除貼皮 ----------
T('K 重設與清除貼皮','清除全部貼皮（含屋頂款式、待套用區域）',()=>{reset();P.roofStyle='clay';sync();SEL.clear();SEL.add(FACES[0].name);P.skinType='brick';applySkin(false);const f=FACES.find(x=>wallOfFace(x)==='front'),it=FLAT.items.find(i=>i.f.name===f.name),poly=[[0,0],[0,0],[0,0],[0,0]];setRect(poly,it.umin+5,it.vmin+5,it.umin+30,it.vmin+20);PEND.push({name:f.name,poly});
 clearAllSkins();runSkins(curP);return {ok:Object.keys(P.skins).length===0&&P.roofStyle==='none'&&PEND.length===0&&skinGeoms.length===0,detail:`皮膚面 ${skinGeoms.length}，屋頂款式 ${P.roofStyle}`};});
T('K 重設與清除貼皮','移除選取貼皮時，屋頂款式的面也能被移除',()=>{reset();P.roofStyle='slate';sync();runSkins(curP);const before=skinGeoms.length;const rf=FACES.filter(f=>Math.abs(f.n[1])>=0.05);SEL.clear();SEL.add(rf[0].name);applySkin(true);runSkins(curP);return {ok:skinGeoms.length<before&&(P.noRoofSkin||[]).includes(rf[0].name),detail:`${before} → ${skinGeoms.length} 個皮膚`};});
T('K 重設與清除貼皮','重新套用貼皮可恢復被移除的屋頂面',()=>{reset();P.roofStyle='slate';sync();const rf=FACES.filter(f=>Math.abs(f.n[1])>=0.05);SEL.clear();SEL.add(rf[0].name);applySkin(true);SEL.clear();SEL.add(rf[0].name);P.skinType='brick';applySkin(false);return {ok:!(P.noRoofSkin||[]).includes(rf[0].name)&&!!P.skins[rf[0].name],detail:'noRoofSkin='+JSON.stringify(P.noRoofSkin)};});
T('K 重設與清除貼皮','重設本步驟 ④：貼皮參數與貼皮全部恢復預設',()=>{reset();P.skinAge=80;P.skinType='wood';sync();SEL.add(FACES[0].name);applySkin(false);resetStep(4);return {ok:Object.keys(P.skins).length===0&&P.skinAge===0&&P.skinType==='brick',detail:`age=${P.skinAge} type=${P.skinType}`};});
T('K 重設與清除貼皮','重設本步驟 ②：屋頂恢復預設、其他步驟設定不受影響',()=>{reset();P.width=140;P.roof='mansard';P.eaveX=15;P.chimOn=true;sync();resetStep(2);return {ok:P.roof==='gable'&&P.eaveX===4&&!P.chimOn&&P.width===140,detail:`roof=${P.roof} eaveX=${P.eaveX} width=${P.width}`};});
T('K 重設與清除貼皮','重設本步驟 ③⑤：窗戶清單與室內牆恢復',()=>{reset();sync();ensureManual();P.winManual.push({wall:'front',c:0,w:10,h:10,y0:5,style:'fixed'});P.iwalls=[newIwall('x')];sync();resetStep(3);const a=P.winManual===null;resetStep(5);return {ok:a&&P.iwalls.length===0,detail:`winManual=${P.winManual} 牆=${P.iwalls.length}`};});
T('K 重設與清除貼皮','重設後可復原（Ctrl+Z）',()=>{reset();sync();commit();P.width=150;sync();commit();resetStep(1);const a=P.width===100;undo();return {ok:a&&P.width===150,detail:`重設後 ${a}，復原後 ${P.width}`};});


// ---------- L. Shift 吸附 ----------
const snapWins=()=>{reset();P.nFront=0;P.nLeft=0;P.nRight=0;sync();ensureManual();P.winManual=[{wall:'front',c:-20,w:10,h:10,y0:8,style:'fixed'},{wall:'front',c:10,w:10,h:10,y0:21,style:'fixed'}];sync();WLAY=WLAY||layoutFaces(FACES.filter(f=>Math.abs(f.n[1])<0.05));};
T('L Shift 吸附','移動時吸附到其他窗戶的邊緣（水平）',()=>{snapWins();const a=winRect(P.winManual[0]),b=winRect(P.winManual[1]);const dx=(b.uL-a.uL)+1.5;const r=winSnapDelta(0,dx,0,new Set([0]));return {ok:Math.abs(a.uL+r.dx-b.uL)<1e-6&&r.gx!==null,detail:`原 ${dx.toFixed(1)} → 吸附 ${r.dx.toFixed(1)}，參考線 u=${r.gx}`};});
T('L Shift 吸附','移動時垂直吸附：結果的某一邊與參考線重合',()=>{snapWins();const a=winRect(P.winManual[0]);let hit=null;for(let dy=0;dy<40;dy+=0.5){const r=winSnapDelta(0,0,dy,new Set([0]));if(r.gy!==null){const vals=[a.v0+r.dy,(a.v0+a.v1)/2+r.dy,a.v1+r.dy];if(vals.some(v=>Math.abs(v-r.gy)<1e-6)){hit={dy,r};break;}}}
 return {ok:!!hit,detail:hit?`dy ${hit.dy} → ${hit.r.dy.toFixed(2)}，參考線 v=${hit.r.gy}`:'沒有吸附'};});
T('L Shift 吸附','吸附到牆面中心與邊緣',()=>{snapWins();const a=winRect(P.winManual[0]);const center=(WLAY.items.find(q=>wallOfFace(q.f)==='front'));const mid=center.umin+center.G.U/2;const r=winSnapDelta(0,(mid-(a.uL+a.uR)/2)+1.2,0,new Set([0]));const nx=(a.uL+a.uR)/2+r.dx;return {ok:Math.abs(nx-mid)<1e-6,detail:`中心 → ${nx.toFixed(2)}（牆中心 ${mid.toFixed(2)}）`};});
T('L Shift 吸附','離所有目標都超過 3mm 時不吸附',()=>{snapWins();let free=null;for(let dx=0.5;dx<90;dx+=0.7){const r=winSnapDelta(0,dx,0,new Set([0]));if(r.gx===null){free=dx;break;}}
 const r=winSnapDelta(0,free,0,new Set([0]));return {ok:free!==null&&r.dx===free,detail:`dx=${free} 無吸附，結果 dx=${r.dx}`};});
T('L Shift 吸附','縮放邊緣吸附（bestSnap）',()=>{const b=bestSnap([19.2],[10,20,30],3);const c=bestSnap([25],[10,20,30],3);return {ok:b&&b.t===20&&c===null,detail:`19.2→${b&&b.t}，25→${c}`};});
T('L Shift 吸附','拖曳事件：預設自動吸附；按住 Shift 暫時關閉',()=>{snapWins();goStep(3);setView('flat');renderFlat();const a=winRect(P.winManual[0]),b=winRect(P.winManual[1]);
 const run=(shift,snapOn)=>{snapWins();P.snapOn=snapOn;WDRAG={h:null,start:[0,0],primary:0,toggle:false,moved:false,items:[{i:0,c:P.winManual[0].c,y0:P.winManual[0].y0,w:10,h0:10,sg:1}]};
  const dx=(b.uL-a.uL)+1.5;elevMove({shiftKey:shift},[dx,0]);const r=winRect(P.winManual[0]).uL;WDRAG=null;GUIDE=null;return r;};
 const auto=run(false,true),off=run(true,true),inv=run(true,false),none=run(false,false);P.snapOn=true;
 return {ok:Math.abs(auto-b.uL)<1e-6&&Math.abs(off-b.uL)>0.5&&Math.abs(inv-b.uL)<1e-6&&Math.abs(none-b.uL)>0.5,detail:`自動吸附 ${auto.toFixed(2)}；Shift 關閉 ${off.toFixed(2)}；吸附關＋Shift 開啟 ${inv.toFixed(2)}；吸附關 ${none.toFixed(2)}（目標 ${b.uL.toFixed(2)}）`};});
T('L Shift 吸附','拖曳時產生間距標註（左右／上下）',()=>{snapWins();const g=gapDims(0,new Set([0]));return {ok:!!g&&g.out.length===4&&g.out.every(x=>isFinite(x.t)),detail:g.out.map(x=>x.t.toFixed(1)).join(' / ')};});
T('L Shift 吸附','吸附距離設定（snapTH）影響吸附範圍',()=>{snapWins();let ok=false,d='';for(let dx=0;dx<60&&!ok;dx+=0.25){P.snapTH=2;const r1=winSnapDelta(0,dx,0,new Set([0]));P.snapTH=8;const r2=winSnapDelta(0,dx,0,new Set([0]));if(r1.gx===null&&r2.gx!==null){ok=true;d=`dx=${dx}：TH2 不吸附、TH8 吸附到 ${r2.gx}`;}}P.snapTH=4;return {ok,detail:d||'找不到差異'};});
T('L Shift 吸附','吸附目標附帶標籤（窗戶左緣／牆中心…）',()=>{snapWins();const a=winRect(P.winManual[0]),b=winRect(P.winManual[1]);const r=winSnapDelta(0,(b.uL-a.uL)+1,0,new Set([0]));return {ok:/窗戶|牆/.test(r.gxl),detail:'標籤 '+r.gxl+'，目標窗 '+r.twx};});
T('L Shift 吸附','參考物件：點選已選窗戶設為參考，對齊以它為準且它不動',()=>{mkWins();winKey=1;const key0=winRect(P.winManual[1]).uL;alignOp('alignL');const L=P.winManual.map(w=>winRect(w).uL);return {ok:L.every(x=>Math.abs(x-key0)<=0.5)&&Math.abs(winRect(P.winManual[1]).uL-key0)<1e-6,detail:`參考左緣 ${key0.toFixed(1)}，結果 ${L.map(x=>x.toFixed(1))}`};});
T('L Shift 吸附','參考物件：水平置中對齊到參考窗的中心',()=>{mkWins();winKey=2;const c0=P.winManual[2].c;alignOp('alignCH');const C=P.winManual.map(w=>w.c);return {ok:C.every(x=>Math.abs(x-c0)<=0.5),detail:`參考中心 ${c0}，結果 ${C}`};});
T('L Shift 吸附','參考物件：點擊切換（keyCand）與取消',()=>{mkWins();WDRAG={h:null,start:[0,0],primary:1,toggle:false,keyCand:true,moved:false,items:[]};elevUp();const a=winKey;WDRAG={h:null,start:[0,0],primary:1,toggle:false,keyCand:true,moved:false,items:[]};elevUp();const b=winKey;return {ok:a===1&&b===-1,detail:`第一次 ${a}，第二次 ${b}`};});
T('L Shift 吸附','選取改變時，不在選取內的參考物件會被清除',()=>{mkWins();winKey=1;setWinSel([0]);return {ok:winKey===-1,detail:'winKey='+winKey};});
T('L 窗戶滑桿即時','個別調整：滑桿即時套用到已選取的窗戶',()=>{mkWins();setWinSel([1]);SETTERS.winW(22);const ok=P.winManual[1].w===22&&P.winManual[0].w===10&&P.winManual[2].w===8;return {ok,detail:P.winManual.map(w=>w.w).join(',')};});
T('L 窗戶滑桿即時','個別調整：沒有選取時套用到全部窗戶',()=>{mkWins();setWinSel([]);SETTERS.winH(16);return {ok:P.winManual.every(w=>w.h===16),detail:P.winManual.map(w=>w.h).join(',')};});
T('L 窗戶滑桿即時','離地滑桿＝0 → 變門；款式按鈕套用到選取的窗戶',()=>{mkWins();setWinSel([0]);SETTERS.winSill(0);const a=P.winManual[0].y0===0;clickSeg('winStyleSeg','拱形窗');return {ok:a&&P.winManual[0].style==='arch'&&P.winManual[1].style==='fixed',detail:`y0=${P.winManual[0].y0} 款式 ${P.winManual.map(w=>w.style)}`};});
T('L 窗戶滑桿即時','選取窗戶時滑桿會顯示該窗戶的數值',()=>{mkWins();setWinSel([1]);const row=k=>[...document.querySelectorAll('.row')].find(r=>r.dataset.k===k).children[2].value;return {ok:+row('winW')===14&&+row('winH')===12&&+row('winSill')===9,detail:`W ${row('winW')} H ${row('winH')} 離地 ${row('winSill')}`};});
T('L 窗戶滑桿即時','參數化模式：滑桿即時改變窗戶（sync）',()=>{reset();P.winW=14;sync();const a=curP.wins.find(w=>!w.main).w;P.winW=20;sync();const b=curP.wins.find(w=>!w.main).w;return {ok:a===14&&b===20,detail:`${a}→${b}`};});
T('L 窗戶滑桿即時','個別調整模式隱藏數量／排數滑桿並顯示提示',()=>{mkWins();sync();const hid=[...document.querySelectorAll('.row')].filter(r=>['winRows','winGap'].includes(r.dataset.k)).every(r=>r.style.display==='none');return {ok:hid&&$('winModeHint').textContent.includes('個別調整模式'),detail:$('winModeHint').textContent.slice(0,30)};});
// ---------- M. 大門與樓梯 ----------
const setDoor=(o)=>{reset();P.doorOn=true;Object.assign(P,o||{});sync();};
T('M 大門','加大門：清單出現貼地的主入口',()=>{setDoor();const d=curP.wins.find(w=>w.main);return {ok:!!d&&d.y0===0&&d.wall==='front'&&d.style==='fixed',detail:JSON.stringify(d)};});
T('M 大門','三種款式對應：單扇／雙開／拱形',()=>{const r={};for(const [k,v] of [['single','fixed'],['double','dbl'],['arch','arch']]){setDoor({doorStyle:k});r[k]=curP.wins.find(w=>w.main).style;}return {ok:r.single==='fixed'&&r.double==='dbl'&&r.arch==='arch',detail:JSON.stringify(r)};});
T('M 大門','牆體被開出門洞（體積減少），款式造成不同開口',()=>{reset();P.nFront=0;P.nBack=0;P.nLeft=0;P.nRight=0;P.winWall={front:false,back:false,left:false,right:false};sync();const v0=vol(cur.body);
 const vv={};for(const k of ['single','double','arch']){setDoor({doorStyle:k,nFront:0,nBack:0,nLeft:0,nRight:0,winWall:{front:false,back:false,left:false,right:false}});vv[k]=vol(cur.body);}
 return {ok:vv.single<v0-50&&vv.double>vv.single+1&&vv.arch>vv.single+1,detail:`無門 ${v0.toFixed(0)} 單扇 ${vv.single.toFixed(0)} 雙開 ${vv.double.toFixed(0)} 拱形 ${vv.arch.toFixed(0)}`};});
T('M 大門','參數化窗戶自動讓開大門位置',()=>{reset();P.nFront=1;sync();const n0=curP.wins.filter(w=>w.wall==='front'&&!w.main).length;setDoor({nFront:1,doorC:0});const n1=curP.wins.filter(w=>w.wall==='front'&&!w.main).length;return {ok:n0===1&&n1===0,detail:`前牆窗 ${n0} → ${n1}`};});
T('M 大門','轉為個別調整時不會把大門複製成窗戶',()=>{setDoor();ensureManual();return {ok:!P.winManual.some(w=>w.main)&&windowList(P).some(w=>w.main),detail:'手動清單 '+P.winManual.length+'，仍含大門：'+windowList(P).some(w=>w.main)};});
T('M 大門','換牆面（後牆）與位置偏移',()=>{setDoor({doorWall:'back',doorC:15});const d=curP.wins.find(w=>w.main);return {ok:d.wall==='back'&&d.c===15,detail:`wall=${d.wall} c=${d.c}`};});
T('M 大門','正視圖拖曳大門：預設吸附牆中心，Shift 暫時關閉',()=>{setDoor({doorC:20});goStep(3);renderFlat();P.snapOn=true;DDRAG={c0:20,start:[0,0],sg:1};elevMove({shiftKey:false},[-19,0]);const a=P.doorC;DDRAG={c0:20,start:[0,0],sg:1};elevMove({shiftKey:true},[-19,0]);const b=P.doorC;DDRAG=null;GUIDE=null;return {ok:Math.abs(a)<1e-6&&Math.abs(b-1)<1e-6,detail:`自動吸附 c=${a}；Shift 關閉 c=${b}`};});
T('M 大門','雷射：大門為底邊缺口；窗洞數正確',()=>{setDoor({print:'laser'});const pn=laserPanels(curP).find(p=>p.name.startsWith('前牆'));const door=curP.wins.find(w=>w.main);const has=pn.outer.some(q=>Math.abs(q[0]-(door.c-door.w/2))<0.01&&Math.abs(q[1]-door.h)<0.01);return {ok:has,detail:'前牆輪廓含門缺口：'+has};});
T('M 大門','大門高度不超過樓層高度',()=>{setDoor({doorH:70});const d=curP.wins.find(w=>w.main);return {ok:d.h<=curP.floorH-1.5,detail:`門高 ${d.h}（層高 ${curP.floorH}）`};});
const stairState=(o)=>{reset();P.floors=2;P.slabOn=true;sync();P.stairs[0].on=true;Object.assign(P.stairs[0],o||{});sync();};
T('N 樓梯','每層樓各有一個開關：3 層樓 → 2 組',()=>{reset();P.floors=3;sync();return {ok:P.stairs.length>=2&&document.querySelectorAll('#stairList .stairBox').length===2,detail:`樓梯設定 ${P.stairs.length}，卡片 ${document.querySelectorAll('#stairList .stairBox').length}`};});
T('N 樓梯','單層樓時沒有樓梯、顯示提示',()=>{reset();P.floors=1;sync();return {ok:document.querySelectorAll('#stairList .stairBox').length===0&&$('stairList').textContent.includes('兩層樓'),detail:$('stairList').textContent.slice(0,30)};});
T('N 樓梯','開啟樓梯：產生踏步實體',()=>{stairState();const sb=stairBoxes(curP),g=stairGeo(curP,P.stairs[0],0);return {ok:sb.steps.length===g.n&&g.n>=3&&extraGeoms.length>=g.n,detail:`${g.n} 階，每階高 ${g.riser.toFixed(2)}，踏深 ${g.tread.toFixed(2)}，長 ${g.run.toFixed(1)}`};});
T('N 樓梯','卡片上的階數與長度為有效數字（無 NaN）',()=>{stairState();renderStairList();const t=$('stairList').textContent;return {ok:!t.includes('NaN')&&/\d+ 階/.test(t),detail:t.replace(/\s+/g,' ').slice(0,90)};});
T('N 樓梯','關閉樓梯：沒有踏步',()=>{stairState();P.stairs[0].on=false;sync();return {ok:stairBoxes(curP).steps.length===0,detail:'steps=0'};});
T('N 樓梯','斜度越陡：階數不變、長度越短',()=>{stairState({slope:30});const a=stairGeo(curP,P.stairs[0],0);stairState({slope:50});const b=stairGeo(curP,P.stairs[0],0);return {ok:b.run<a.run*0.7&&a.n===b.n,detail:`30° 長 ${a.run.toFixed(1)}；50° 長 ${b.run.toFixed(1)}`};});
T('N 樓梯','每階高決定階數（2.5→5mm，階數減半）',()=>{stairState({riserH:2.5});const a=stairGeo(curP,P.stairs[0],0);stairState({riserH:5});const b=stairGeo(curP,P.stairs[0],0);return {ok:Math.abs(a.n/b.n-2)<0.3,detail:`${a.n} 階 → ${b.n} 階`};});
T('N 樓梯','方向：+X／−Z 的踏步延伸方向正確',()=>{const ext={};for(const d of ['+x','-x','+z','-z']){stairState({dir:d,x:0,z:0});const st=stairBoxes(curP).steps;ext[d]=[Math.min(...st.map(b=>b.cx-b.sx/2)),Math.max(...st.map(b=>b.cx+b.sx/2)),Math.min(...st.map(b=>b.cz-b.sz/2)),Math.max(...st.map(b=>b.cz+b.sz/2))].map(v=>+v.toFixed(1));}
 return {ok:ext['+x'][0]>=-0.01&&ext['+x'][1]>5&&ext['-x'][1]<=0.01&&ext['-x'][0]<-5&&ext['+z'][2]>=-0.01&&ext['+z'][3]>5&&ext['-z'][3]<=0.01&&ext['-z'][2]<-5,detail:JSON.stringify(ext)};});
T('N 樓梯','位置：起點座標移動踏步位置',()=>{stairState({x:-10,z:5});const a=stairBoxes(curP).steps[0];stairState({x:-10+7,z:5+3});const b=stairBoxes(curP).steps[0];return {ok:Math.abs(b.cx-a.cx-7)<1e-6&&Math.abs(b.cz-a.cz-3)<1e-6,detail:`Δx=${(b.cx-a.cx).toFixed(2)} Δz=${(b.cz-a.cz).toFixed(2)}`};});
T('N 樓梯','樓板開口：有樓梯時 2F 樓板體積較小',()=>{reset();P.floors=2;P.slabOn=true;sync();const v0=vol(extraGeoms.find(g=>Math.abs(bbox(g).y-curP.floorT)<0.01&&g.boundingBox.min.y>5));
 stairState();const slab=extraGeoms.find(g=>{bbox(g);return Math.abs(g.boundingBox.min.y-curP.floorH)<0.01;});const v1=vol(slab);return {ok:v1<v0-5,detail:`${v0.toFixed(0)} → ${v1.toFixed(0)} mm³`};});
T('N 樓梯','超出室內範圍時警告',()=>{stairState({x:40,z:0,dir:'+x',slope:20});const w=stairWarnings(curP);return {ok:w.some(x=>x.includes('超出室內')),detail:w[0]||'無警告'};});
T('N 樓梯','範圍內沒有超出警告',()=>{stairState({x:-30,z:10,dir:'+x',slope:40});const w=stairWarnings(curP).filter(x=>x.includes('超出'));return {ok:w.length===0,detail:'警告 '+w.length};});
T('N 樓梯','平面圖顯示樓梯與方向控制點',()=>{stairState();goStep(5);setView('flat');renderFlat();const h=$('flat').innerHTML;return {ok:(h.match(/data-stair/g)||[]).length>=g_n()&&h.includes('data-sdir'),detail:'樓梯元素 '+(h.match(/data-stair/g)||[]).length};});
function g_n(){return stairGeo(curP,P.stairs[0],0).n;}
T('N 樓梯','平面圖拖曳：移動起點與旋轉方向',()=>{stairState({x:0,z:0,dir:'+x'});const op=planPoint;PDRAG={stair:0,start:[0,0],x0:0,z0:0};planPoint=()=>[6,-4];planMove({});const a=[P.stairs[0].x,P.stairs[0].z];PDRAG={sdir:0,start:[0,0]};planPoint=()=>[2,-20];planMove({});const dir=P.stairs[0].dir;planPoint=op;PDRAG=null;return {ok:a[0]===6&&a[1]===-4&&dir==='-z',detail:`起點 ${a}，方向 ${dir}`};});
T('N 樓梯','雷射：側板×2＋踏板＋立板',()=>{stairState({print:'laser'});P.print='laser';sync();const g=stairGeo(curP,P.stairs[0],0),pn=laserPanels(curP).filter(p=>p.name.includes('樓梯')||p.name.includes('踏板')||p.name.includes('踢板'));return {ok:pn.length===2+2*g.n,detail:`零件 ${pn.length}（${g.n} 階）`};});
T('N 樓梯','STL 匯出包含樓梯',()=>{reset();P.floors=2;P.slabOn=true;sync();const a=stlBytes(collectGeoms('all'));P.stairs[0].on=true;sync();const b=stlBytes(collectGeoms('all'));return {ok:b>a,detail:`${(a/1024).toFixed(0)}KB → ${(b/1024).toFixed(0)}KB`};});
T('N 樓梯','重設步驟⑤會清除樓梯',()=>{stairState();resetStep(5);ensureStairs();return {ok:!P.stairs.some(s=>s.on),detail:'樓梯全部關閉'};});


// ---------- Q. 材質預覽 ----------
T('Q 材質預覽','預覽縮圖數量＝材質數（不含「無」）',()=>{reset();sync();refreshSwatches(true);const n=Object.keys(SKINS).length-1;return {ok:document.querySelectorAll('#swatches .sw').length===n&&n>=20,detail:`縮圖 ${document.querySelectorAll('#swatches .sw').length} / 材質 ${n}`};});
T('Q 材質預覽','每張縮圖都有明暗變化（不是純色）',()=>{refreshSwatches(true);let flat=[];for(const b of document.querySelectorAll('#swatches .sw')){const c=b.querySelector('canvas'),d=c.getContext('2d').getImageData(0,0,c.width,c.height).data;let mn=255,mx=0;for(let i=0;i<d.length;i+=4){const l=(d[i]+d[i+1]+d[i+2])/3;mn=Math.min(mn,l);mx=Math.max(mx,l);}if(mx-mn<8)flat.push(b.dataset.t);}return {ok:flat.length===0,detail:flat.length?'幾乎純色：'+flat.join(','):'全部有明暗變化'};});
T('Q 材質預覽','縮圖會隨紋理比例改變',()=>{const px=(sc)=>{const c=patSwatch('brick',sc,0,7,0.8),d=c.getContext('2d').getImageData(0,0,c.width,c.height).data;let s=0;for(let i=0;i<d.length;i+=4)s+=d[i]*(i%97+1);return s;};return {ok:Math.abs(px(0.5)-px(2))>1000,detail:`差異 ${Math.abs(px(0.5)-px(2)).toFixed(0)}`};});
T('Q 材質預覽','縮圖會隨舊化程度改變（裂痕出現）',()=>{const px=(a)=>{const c=patSwatch('brick',1,a,7,0.8),d=c.getContext('2d').getImageData(0,0,c.width,c.height).data;let s=0;for(let i=0;i<d.length;i+=4)s+=d[i]*(i%89+1);return s;};return {ok:Math.abs(px(0)-px(80))>1000,detail:`差異 ${Math.abs(px(0)-px(80)).toFixed(0)}`};});
T('Q 材質預覽','點選縮圖：套用為目前材質並標示選取',()=>{reset();goStep(4);sync();refreshSwatches(true);const b=[...document.querySelectorAll('#swatches .sw')].find(x=>x.dataset.t==='slate');b.click();const on=[...document.querySelectorAll('#swatches .sw.on')].map(x=>x.dataset.t);return {ok:P.skinType==='slate'&&on.length===1&&on[0]==='slate',detail:`skinType=${P.skinType} 高亮 ${on}`};});
T('Q 材質預覽','更新參數後縮圖重新產生（signature）',()=>{reset();goStep(4);sync();refreshSwatches(true);const a=document.querySelector('#swatches .sw canvas');P.skinAge=70;sync();const b=document.querySelector('#swatches .sw canvas');return {ok:a!==b,detail:'縮圖已重建'};});


// ---------- R. 樓梯進階（型式、結構、扶手、接續）----------
const st3=(o,o2)=>{reset();P.floors=3;P.slabOn=true;P.floorOn=true;sync();P.stairs[0].on=true;Object.assign(P.stairs[0],o||{});if(o2){P.stairs[1].on=true;Object.assign(P.stairs[1],o2);}sync();};
T('R 樓梯進階','L 型：兩段飛梯＋平台，階數加總＝總階數',()=>{st3({type:'L',x:-35,z:-30,slope:40});const L=resolveStairs(curP)[0].lay,n=L.fl.reduce((a,f)=>a+f.n,0);return {ok:L.fl.length===2&&!!L.landing&&n===L.g.n,detail:`飛梯 ${L.fl.map(f=>f.n)}，平台 ${!!L.landing}，總階 ${L.g.n}`};});
T('R 樓梯進階','L 型：第二段方向＝第一段轉 90°（右轉 / 左轉）',()=>{st3({type:'L',turn:'right',dir:'+x'});const a=resolveStairs(curP)[0].lay.fl[1].d.join(',');st3({type:'L',turn:'left',dir:'+x'});const b=resolveStairs(curP)[0].lay.fl[1].d.join(',');return {ok:a==='0,1'&&b==='0,-1',detail:`右轉 → ${a}；左轉 → ${b}（+X 出發）`};});
T('R 樓梯進階','U 型：第二段與第一段反向並排，平台橫跨兩段',()=>{st3({type:'U',turn:'right',dir:'+x'});const L=resolveStairs(curP)[0].lay;const d1=L.fl[0].d,d2=L.fl[1].d;return {ok:d2[0]===-d1[0]&&d2[1]===-d1[1]&&L.landing.sz>L.fl[0].w,detail:`方向 ${d1} → ${d2}，平台 ${L.landing.sx.toFixed(0)}×${L.landing.sz.toFixed(0)}`};});
T('R 樓梯進階','平台高度＝第一段終點高度，第二段從平台往上',()=>{st3({type:'L'});const L=resolveStairs(curP)[0].lay;return {ok:Math.abs(L.landing.y1-L.fl[1].base)<1e-6&&L.fl[1].base>L.fl[0].base,detail:`平台頂 ${L.landing.y1.toFixed(2)}，第二段起 ${L.fl[1].base.toFixed(2)}`};});
T('R 樓梯進階','實心／鏤空：鏤空每階為「踏板＋兩側梁」共 3 塊',()=>{st3({struct:'solid'});const a=stairBoxes(curP).steps.length;st3({struct:'open'});const b=stairBoxes(curP).steps.length;return {ok:b===a*3,detail:`實心 ${a} 塊，鏤空 ${b} 塊`};});
T('R 樓梯進階','鏤空樓梯的體積小於實心',()=>{st3({struct:'solid'});const a=stairBoxes(curP).steps.reduce((s,b)=>s+b.sx*b.sy*b.sz,0);st3({struct:'open'});const b=stairBoxes(curP).steps.reduce((s,x)=>s+x.sx*x.sy*x.sz,0);return {ok:b<a*0.6,detail:`${a.toFixed(0)} → ${b.toFixed(0)} mm³`};});
T('R 樓梯進階','扶手：左／右／兩側產生欄杆實體',()=>{const r={};for(const k of ['none','left','right','both']){st3({rail:k});r[k]=stairBoxes(curP).rails.length;}return {ok:r.none===0&&r.left>0&&r.right>0&&r.both===r.left+r.right,detail:JSON.stringify(r)};});
T('R 樓梯進階','扶手進入 3D 實體與 STL',()=>{st3({rail:'none'});const a=extraGeoms.length;st3({rail:'both'});return {ok:extraGeoms.length>a,detail:`${a} → ${extraGeoms.length}`};});
T('R 樓梯進階','自動接續（直行）：第二層起點＝第一層終點，方向相同',()=>{st3({type:'straight',x:-40,z:20,dir:'+x'},{chain:true,chainTurn:'straight'});const R2=resolveStairs(curP),E=R2[0].lay.end;const s2=R2[1].st;return {ok:Math.abs(s2.x-E.x)<=0.5&&Math.abs(s2.z-E.z)<=0.5&&s2.dir==='+x',detail:`終點 (${E.x.toFixed(1)},${E.z.toFixed(1)})，下一層起點 (${s2.x},${s2.z}) 方向 ${s2.dir}`};});
T('R 樓梯進階','自動接續（迴轉）：方向相反並排',()=>{st3({x:-40,z:20,dir:'+x'},{chain:true,chainTurn:'back'});const s2=resolveStairs(curP)[1].st;return {ok:s2.dir==='-x'&&Math.abs(s2.z-20)>=curP.floorT,detail:`方向 ${s2.dir}，Z=${s2.z}`};});
T('R 樓梯進階','自動接續（右轉／左轉）：方向轉 90°',()=>{st3({x:-40,z:0,dir:'+x'},{chain:true,chainTurn:'right'});const a=resolveStairs(curP)[1].st.dir;st3({x:-40,z:0,dir:'+x'},{chain:true,chainTurn:'left'});const b=resolveStairs(curP)[1].st.dir;return {ok:a==='+z'&&b==='-z',detail:`右轉 ${a}，左轉 ${b}`};});
T('R 樓梯進階','關閉自動接續後可自訂起點與方向',()=>{st3({x:-40,z:20,dir:'+x'},{chain:false,x:10,z:-10,dir:'-z'});const s2=resolveStairs(curP)[1].st;return {ok:s2.x===10&&s2.z===-10&&s2.dir==='-z',detail:`(${s2.x},${s2.z}) ${s2.dir}`};});
T('R 樓梯進階','手動改起點／方向會自動關閉接續（UI）',()=>{st3({x:-40,z:20},{chain:true});renderStairList();const inp=document.querySelectorAll('#stairList .stairBox')[1].querySelector('[data-s=x]');const dis=inp.disabled;return {ok:dis===true,detail:'接續中：起點欄位停用 = '+dis};});
T('R 樓梯進階','平面圖：每層頂視圖各自顯示平台、扶手線、「接續」標籤與樓下來的淡色樓梯',()=>{st3({type:'L',rail:'both'},{chain:true});goStep(5);setView('flat');renderFlat();const h=$('flat').innerHTML;return {ok:h.includes('平台')&&h.includes('接續')&&h.includes('樓下來'),detail:'1F 圖含平台；2F 圖含「接續」與樓下來的淡色樓梯'};});
T('R 樓梯進階','雷射：L 型樓梯含平台與兩段側板',()=>{st3({type:'L',print:'laser'});P.print='laser';sync();const pn=laserPanels(curP).filter(p=>p.name.includes('樓梯')||p.name.includes('踏板')||p.name.includes('踢板'));return {ok:pn.some(p=>p.name.includes('平台'))&&pn.filter(p=>p.name.includes('側板')).length===4,detail:`零件 ${pn.length}`};});
T('R 樓梯進階','樓板洞只開在最後一段（L 型）',()=>{st3({type:'L',x:-35,z:-30});const h=stairBoxes(curP).holes.filter(x=>x.level===1);return {ok:h.length===1,detail:'洞數 '+h.length};});
T('R 樓梯進階','超出範圍警告（直跑過長）並建議 L／U',()=>{st3({type:'straight',x:40,z:0,slope:18});const w=stairWarnings(curP);return {ok:w.some(x=>x.includes('L／U')),detail:w[0]||'無'};});


// ---------- S. 樓層圖層（室內／窗戶正視圖） ----------
const flr=(o)=>{reset();P.floors=3;P.slabOn=true;P.floorOn=true;Object.assign(P,o||{});sync();renderFloorTabs();};
T('S 樓層圖層','樓層分頁：每層一個分頁',()=>{flr();return {ok:document.querySelectorAll('#floorTabs button').length===3,detail:'分頁 '+document.querySelectorAll('#floorTabs button').length};});
T('S 樓層圖層','新增的牆屬於目前編輯的樓層',()=>{flr({planFloor:1});$('addWallX').click();const w=P.iwalls[P.iwalls.length-1];return {ok:w.floor===1,detail:'floor='+w.floor};});
T('S 樓層圖層','圖層牆只有一層高（≈層高），舊版貫穿牆為總高',()=>{flr();P.iwalls=[{axis:'x',floor:1,pos:0,a0:-30,a1:30,doors:[]}];sync();const h1=bbox(iwGeoms[0]).y;P.iwalls=[{axis:'x',pos:0,a0:-30,a1:30,doors:[]}];sync();const h2=bbox(iwGeoms[0]).y;return {ok:Math.abs(h1-(curP.floorH+0.3))<0.6&&Math.abs(h2-curP.wallH)<0.6,detail:`圖層牆 ${h1.toFixed(1)}（層高 ${curP.floorH}），舊版 ${h2.toFixed(1)}（總高 ${curP.wallH}）`};});
T('S 樓層圖層','圖層牆的門只出現在自己的樓層',()=>{flr();const a=iwDoors(curP,{floor:1,doors:[{c:0,w:10,h:15}]}).length;const b=iwDoors(curP,{doors:[{c:0,w:10,h:15}]}).length;return {ok:a===1&&b===3,detail:`圖層牆 ${a} 個門，舊版 ${b} 個門（3 層）`};});
T('S 樓層圖層','步驟⑤：每一層各有一張獨立頂視圖（同時並排，不疊在一起）',()=>{flr({planFloor:1});P.iwalls=[{axis:'x',floor:0,pos:-10,a0:-40,a1:40,doors:[]},{axis:'z',floor:1,pos:10,a0:-40,a1:40,doors:[]},{axis:'x',floor:2,pos:20,a0:-30,a1:30,doors:[]}];sync();goStep(5);setView('flat');renderFlat();const h=$('flat').innerHTML;
 const groups=(h.match(/data-pfg="/g)||[]).length,labels=['1F 頂視圖','2F 頂視圖','3F 頂視圖'].every(x=>h.includes(x));
 const own=f=>{const g=h.split('data-pfg="'+f+'"')[1].split('data-pfg="')[0];return (g.match(/data-iw="/g)||[]).length;};
 return {ok:groups===3&&labels&&own(0)===1&&own(1)===1&&own(2)===1,detail:`頂視圖 ${groups} 張；各層牆數 ${own(0)}/${own(1)}/${own(2)}（各層只畫自己的牆）`};});
T('S 樓層圖層','頂視圖數量隨樓層數增加（1→4 層）',()=>{const r=[];for(const F of [1,2,3,4]){reset();P.floors=F;sync();goStep(5);setView('flat');renderFlat();r.push((($('flat').innerHTML.match(/data-pfg="/g))||[]).length);}return {ok:r.join()==='1,2,3,4',detail:'樓層 1~4 → 頂視圖 '+r.join(',')};});
T('S 樓層圖層','點選某層頂視圖空白處＝切換為目前編輯層',()=>{flr({planFloor:0});goStep(5);setView('flat');renderFlat();const bg=$('flat').querySelector('[data-pbg="2"]');bg.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,button:0,buttons:1,pointerId:9}));return {ok:P.planFloor===2&&document.querySelector('#floorTabs .on').textContent==='3F',detail:'planFloor='+P.planFloor};});
T('S 樓層圖層','在某層頂視圖點選牆＝自動切換到該層並選取',()=>{flr({planFloor:0});P.iwalls=[{axis:'x',floor:1,pos:0,a0:-30,a1:30,doors:[]}];sync();goStep(5);setView('flat');renderFlat();const el=$('flat').querySelector('[data-iw="0"]');el.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,button:0,buttons:1,pointerId:9,clientX:100,clientY:100}));planUp();return {ok:P.planFloor===1&&iwSel===0,detail:`planFloor=${P.planFloor} iwSel=${iwSel}`};});
T('S 樓層圖層','各層頂視圖的座標相互獨立（拖曳第 2 層的牆不影響第 1 層）',()=>{flr({planFloor:1});P.iwalls=[{axis:'x',floor:0,pos:0,a0:-30,a1:30,doors:[]},{axis:'x',floor:1,pos:0,a0:-30,a1:30,doors:[]}];sync();PDRAG={i:1,pf:1,start:[0,0],pos0:0,c0:0,a0:-30,a1:30,door:null};const op=planPoint;planPoint=()=>[0,7];planMove({});planPoint=op;PDRAG=null;return {ok:P.iwalls[1].pos===7&&P.iwalls[0].pos===0,detail:`1F 牆 pos=${P.iwalls[0].pos}，2F 牆 pos=${P.iwalls[1].pos}`};});
T('S 樓層圖層','牆清單只列目前圖層',()=>{flr({planFloor:0});P.iwalls=[{axis:'x',floor:0,pos:0,a0:-20,a1:20,doors:[]},{axis:'x',floor:2,pos:5,a0:-20,a1:20,doors:[]}];renderIwList();const n=document.querySelectorAll('#iwList .card').length;P.planFloor=2;renderIwList();const m=document.querySelectorAll('#iwList .card').length;P.planFloor=0;return {ok:n===1&&m===1,detail:`1F ${n} 張、3F ${m} 張`};});
T('S 樓層圖層','範本只取代同一層的牆',()=>{flr({planFloor:0});P.iwalls=[{axis:'x',floor:1,pos:0,a0:-20,a1:20,doors:[]}];$('preCross').click();const f0=P.iwalls.filter(w=>w.floor===0).length,f1=P.iwalls.filter(w=>w.floor===1).length;return {ok:f0===2&&f1===1,detail:`1F ${f0} 面（範本）、2F ${f1} 面（保留）`};});
T('S 樓層圖層','複製此層的牆到其他樓層',()=>{flr({planFloor:0});P.iwalls=[{axis:'x',floor:0,pos:0,a0:-20,a1:20,doors:[]}];$('copyFloor').click();const c=[0,1,2].map(f=>P.iwalls.filter(w=>w.floor===f).length);return {ok:c.every(x=>x===1),detail:'各層牆數 '+c};});
T('S 樓層圖層','雷射：圖層牆標示樓層且高度為層高',()=>{flr({print:'laser'});P.print='laser';P.iwalls=[{axis:'x',floor:1,pos:0,a0:-30,a1:30,doors:[]}];sync();const pn=laserPanels(curP).find(p=>p.name.includes('2F 室內牆'));const ys=pn.outer.map(q=>q[1]);return {ok:!!pn&&Math.abs(Math.max(...ys)-(curP.floorH+0.3))<0.6,detail:pn?pn.name+' 高 '+Math.max(...ys).toFixed(1):'找不到'};});
T('S 樓層圖層','窗戶正視圖：選定樓層以外的窗戶淡化且不可選',()=>{flr();P.winManual=null;P.nFront=1;P.winRows=1;sync();ensureManual();P.winManual=[{wall:'front',c:0,w:10,h:8,y0:5,style:'fixed'},{wall:'front',c:20,w:10,h:8,y0:25,style:'fixed'}];P.elevFloor=1;sync();goStep(3);setView('flat');renderFlat();const h=$('flat').innerHTML;const act=(h.match(/data-win="/g)||[]).length;P.elevFloor='all';return {ok:act<4&&h.includes('data-win="1"')&&!h.includes('data-win="0"'),detail:`可互動窗戶元素 ${act}`};});
T('S 樓層圖層','正視圖樓層分頁（全部＋每層）',()=>{flr();renderElevTabs();return {ok:document.querySelectorAll('#elevTabs button').length===4,detail:'分頁 '+document.querySelectorAll('#elevTabs button').length};});
// ---------- T. 周邊小型建築 ----------
const an=(list)=>{reset();P.annex=list;sync();};
T('T 周邊小型建築','附屬車庫：產生牆＋屋頂實體並位於主屋右側',()=>{an([newAnnex('garage',{side:'right',gap:0})]);const it=annexItems[0];return {ok:annexItems.length===1&&it.geoms.length===2&&it.cx>curP.width/2,detail:`實體 ${it.geoms.length}，中心 X=${it.cx.toFixed(1)}（主屋半寬 ${curP.width/2}）`};});
T('T 周邊小型建築','車庫門洞：車庫牆體積小於無門洞',()=>{an([newAnnex('garage',{side:'right'})]);const it=annexItems[0],cut=vol(it.geoms[1]);const cur2=build(it.pe);const full=vol(cur2.body);return {ok:cut<full-100,detail:`有門洞 ${cut.toFixed(0)} < 無門洞 ${full.toFixed(0)}`};});
T('T 周邊小型建築','四個方位都能放置（右／左／前／後）',()=>{const r={};for(const s of ['right','left','front','back']){an([newAnnex('shed',{side:s})]);const it=annexItems[0];r[s]=[+it.cx.toFixed(0),+it.cz.toFixed(0)];}
 return {ok:r.right[0]>50&&r.left[0]<-50&&r.front[1]>50&&r.back[1]<-50,detail:JSON.stringify(r)};});
T('T 周邊小型建築','門廊：只有屋頂板、4 根柱、地台',()=>{an([newAnnex('porch',{side:'front'})]);const it=annexItems[0];return {ok:it.posts.length===4&&!!it.deck&&it.geoms.length===1+4+1,detail:`柱 ${it.posts.length}，地台 ${!!it.deck}，實體 ${it.geoms.length}`};});
T('T 周邊小型建築','車棚：平頂＋4 根柱',()=>{an([newAnnex('carport',{side:'left'})]);const it=annexItems[0];return {ok:it.posts.length===4&&!it.deck&&it.a.roof==='flat',detail:`柱 ${it.posts.length}`};});
T('T 周邊小型建築','美式住宅組合：車庫＋門廊＋工具棚',()=>{reset();sync();$('annexAmerican').click();return {ok:P.annex.length===3&&annexItems.length===3&&P.annex.map(a=>a.type).join()==='garage,porch,shed',detail:P.annex.map(a=>ANNEXTYPES[a.type]).join('、')};});
T('T 周邊小型建築','附屬建築進入 STL 實體、整體範圍變大',()=>{reset();sync();const a=bbox(cur.g),n0=extraGeoms.length;$('annexAmerican').click();const n1=extraGeoms.length;return {ok:n1>n0+5,detail:`額外實體 ${n0} → ${n1}`};});
T('T 周邊小型建築','屋頂型式與屋頂高度可調（雙斜／單斜／平頂）',()=>{const v={};for(const r of ['gable','shed','flat']){an([newAnnex('garage',{roof:r,rise:r==='flat'?0:12})]);v[r]=vol(annexItems[0].geoms[0]);}return {ok:v.gable>0&&v.shed>0&&v.flat>0&&v.gable!==v.shed,detail:JSON.stringify(Object.fromEntries(Object.entries(v).map(([k,x])=>[k,+x.toFixed(0)])))};});
T('T 周邊小型建築','雷射：附屬建築牆與屋頂零件、柱',()=>{reset();P.print='laser';P.annex=[newAnnex('garage',{}),newAnnex('porch',{side:'front'})];sync();const pn=laserPanels(curP).map(p=>p.name);return {ok:pn.some(n=>n.startsWith('車庫 '))&&pn.some(n=>n.startsWith('門廊 柱')),detail:`車庫零件 ${pn.filter(n=>n.startsWith('車庫')).length}，門廊零件 ${pn.filter(n=>n.startsWith('門廊')).length}`};});
T('T 周邊小型建築','清除全部附屬建築、刪除單一',()=>{reset();sync();$('annexAmerican').click();document.querySelector('#annexList .stairBox button').click();const a=P.annex.length;$('annexClear').click();return {ok:a===2&&P.annex.length===0&&annexItems.length===0,detail:`刪除後 ${a}，清除後 ${P.annex.length}`};});
T('T 周邊小型建築','重設步驟①會清除附屬建築',()=>{reset();$('annexAmerican').click();resetStep(1);return {ok:P.annex.length===0,detail:'annex='+P.annex.length};});
// ---------- U. 2D 縮放平移 ----------
T('U 2D 縮放','各步驟平面圖皆可縮放（步驟 3／4／5／6）',()=>{const r=[];for(const st of [3,4,5,6]){reset();if(st===6){P.print='laser';}sync();goStep(st);setView('flat');renderFlat();const svg=flatSvg();if(!svg){r.push(st+':無圖');continue;}const w0=+svg.getAttribute('viewBox').split(/[ ,]+/)[2];zoomAt(2,300,300);const w1=+flatSvg().getAttribute('viewBox').split(/[ ,]+/)[2];zoomFit();r.push(`${st}:${(w0/w1).toFixed(2)}x`);}
 return {ok:r.every(x=>/:[1-3]\.\d+x/.test(x)&&parseFloat(x.split(':')[1])>1.5),detail:r.join('  ')};});
T('U 2D 縮放','縮小／放大有上下限、符合視窗可還原',()=>{reset();sync();goStep(5);setView('flat');renderFlat();for(let i=0;i<30;i++)zoomAt(2,300,300);const w=+flatSvg().getAttribute('viewBox').split(/[ ,]+/)[2],b=baseVB(flatSvg())[2];for(let i=0;i<30;i++)zoomAt(0.5,300,300);const w2=+flatSvg().getAttribute('viewBox').split(/[ ,]+/)[2];zoomFit();const w3=+flatSvg().getAttribute('viewBox').split(/[ ,]+/)[2];return {ok:w>=b/16-1e-6&&w2<=b*1.2+1e-6&&Math.abs(w3-b)<1e-6,detail:`最大放大 ${(b/w).toFixed(1)}x，最小 ${(b/w2).toFixed(2)}x，還原寬 ${w3.toFixed(1)}`};});
T('U 2D 縮放','滾輪事件縮放（以游標為中心）',()=>{reset();sync();goStep(5);setView('flat');renderFlat();const el=$('flat'),r=flatSvg().getBoundingClientRect();const ev=new WheelEvent('wheel',{deltaY:-300,clientX:r.left+r.width/2,clientY:r.top+r.height/2,cancelable:true,bubbles:true});el.dispatchEvent(ev);const z=ZV[P.step];return {ok:!!z&&z.w<z.bw&&ev.defaultPrevented,detail:z?`寬 ${z.bw.toFixed(1)} → ${z.w.toFixed(1)}`:'無縮放狀態'};});
T('U 2D 縮放','重繪後保留縮放狀態',()=>{reset();sync();goStep(5);setView('flat');renderFlat();zoomAt(2,300,300);const a=flatSvg().getAttribute('viewBox');renderFlat();const b=flatSvg().getAttribute('viewBox');zoomFit();return {ok:a===b,detail:b};});
T('U 2D 縮放','平移：拖曳改變 viewBox 位置、寬高不變',()=>{reset();sync();goStep(5);setView('flat');renderFlat();zoomAt(2,300,300);const a=flatSvg().getAttribute('viewBox').split(/[ ,]+/).map(Number);const z=ZV[P.step];ZV[P.step]={...z,x:z.x+10,y:z.y+5};applyZoom();const b=flatSvg().getAttribute('viewBox').split(/[ ,]+/).map(Number);zoomFit();return {ok:Math.abs(b[0]-a[0]-10)<1e-6&&Math.abs(b[2]-a[2])<1e-6,detail:`x ${a[0].toFixed(1)}→${b[0].toFixed(1)}`};});
T('U 2D 縮放','縮放工具列顯示百分比與按鈕',()=>{reset();sync();goStep(5);setView('flat');renderFlat();zoomAt(2,300,300);const t=$('zPct').textContent;zoomFit();return {ok:t.endsWith('%')&&parseInt(t)>150&&$('zoomBar').style.display==='flex',detail:'顯示 '+t};});


// ---------- V. X 光與透視／正交 ----------
const withInterior=()=>{reset();P.floors=2;P.slabOn=true;P.floorOn=true;P.iwalls=[{axis:'x',floor:0,pos:0,a0:-30,a1:30,doors:[]}];sync();ensureStairs();P.stairs[0].on=true;sync();};
T('V X光與投影','預設為不透明（X光關）：外殼擋住室內',()=>{withInterior();return {ok:P.xray===false&&mat.transparent===false&&mat.opacity===1&&$('xrayBtn').textContent==='X光：關',detail:`transparent=${mat.transparent} opacity=${mat.opacity} 按鈕「${$('xrayBtn').textContent}」`};});
T('V X光與投影','X光開：外殼半透明、不寫入深度、按鈕顯示「X光：開」',()=>{withInterior();$('xrayBtn').click();const ok=P.xray&&mat.transparent&&mat.opacity<0.4&&mat.depthWrite===false&&$('xrayBtn').textContent==='X光：開';$('xrayBtn').click();return {ok,detail:`opacity=${mat.opacity}`};});
T('V X光與投影','X光開：室內牆、樓板、樓梯改用暖色材質；關閉後恢復',()=>{withInterior();$('xrayBtn').click();const inner=[...iwGroup.children,...extraGroup.children].filter(m=>m.userData.inner),on=inner.length>0&&inner.every(m=>m.material===matIn);$('xrayBtn').click();const off=inner.every(m=>m.material===mat);return {ok:on&&off,detail:`內部網格 ${inner.length}：開=${on} 關=${off}`};});
T('V X光與投影','外部構件（窗框、附屬建築）不受室內暖色影響',()=>{withInterior();P.frameOn=true;P.annex=[newAnnex('garage',{})];sync();$('xrayBtn').click();const outer=extraGroup.children.filter(m=>!m.userData.inner);const ok=outer.length>0&&outer.every(m=>m.material===mat);$('xrayBtn').click();return {ok,detail:`外部網格 ${outer.length}`};});
T('V X光與投影','X光開啟時自動顯示輪廓線（方便辨識外殼）',()=>{withInterior();P.showEdges=false;$('xrayBtn').click();const a=edges.visible;$('xrayBtn').click();const b=edges.visible;return {ok:a===true&&b===false,detail:`開 ${a}、關 ${b}`};});
T('V X光與投影','X光狀態存入專案並可還原',()=>{withInterior();$('xrayBtn').click();const j=JSON.stringify(P);$('xrayBtn').click();applyState(JSON.parse(j));const ok=P.xray===true&&mat.transparent===true;$('xrayBtn').click();return {ok,detail:'載入後 transparent='+mat.transparent};});
T('V X光與投影','切換到正交：相機型別、控制器、按鈕狀態',()=>{setProjection(true);const ok=cam.isOrthographicCamera&&ctl.object===cam&&P.ortho&&$('projO').classList.contains('on')&&!$('projP').classList.contains('on');setProjection(false);return {ok,detail:`cam=${cam.type}`};});
T('V X光與投影','正交→透視：還原成透視相機，視角方向不變',()=>{camP.position.set(150,120,180);ctl.target.set(0,20,0);ctl.update();const d0=camP.position.clone().sub(ctl.target).normalize();setProjection(true);setProjection(false);const d1=cam.position.clone().sub(ctl.target).normalize();return {ok:cam.isPerspectiveCamera&&d0.distanceTo(d1)<1e-6,detail:'方向差 '+d0.distanceTo(d1).toExponential(1)};});
T('V X光與投影','正交畫面大小與透視切換前相當（物體不會突然變大／變小）',()=>{camP.position.set(150,120,180);ctl.target.set(0,20,0);const dist=camP.position.distanceTo(ctl.target),vh=2*dist*Math.tan(camP.fov*Math.PI/360);setProjection(true);const h=camO.top-camO.bottom;setProjection(false);return {ok:Math.abs(h-vh)<1e-6,detail:`視野高 ${vh.toFixed(1)} → ${h.toFixed(1)}`};});
T('V X光與投影','正交模式下視角立方體與標籤仍可投影、視角按鈕可用',()=>{setProjection(true);camView('front');const f=cam.position.clone().sub(ctl.target);const ok=Math.abs(f.x)<1e-3&&f.z>0;_v.set(0,0,curP.depth/2+10).project(cam);const fin=isFinite(_v.x)&&isFinite(_v.y);setProjection(false);return {ok:ok&&fin,detail:`前視 方向 (${f.x.toFixed(1)},${f.y.toFixed(1)},${f.z.toFixed(1)})`};});
T('V X光與投影','正交模式下滑鼠點選面（射線）可用',()=>{reset();sync();setProjection(true);camView('front');ctl.update();goStep(4);const r=ren.domElement.getBoundingClientRect();const n=pickAt({clientX:r.left+r.width/2,clientY:r.top+r.height*0.6});setProjection(false);return {ok:typeof n==='string'||n===null,detail:'命中 '+n};});
T('V X光與投影','視窗大小改變時正交視野跟著調整',()=>{setProjection(true);const w0=camO.right-camO.left;camAspect(1000,500);const w1=camO.right-camO.left;camAspect(500,500);const w2=camO.right-camO.left;resize();setProjection(false);return {ok:Math.abs(w1/w2-2)<1e-6,detail:`寬 ${w1.toFixed(1)} / ${w2.toFixed(1)}`};});
T('V X光與投影','專案存檔含投影設定並可還原',()=>{setProjection(true);const j=JSON.stringify(P);setProjection(false);applyState(JSON.parse(j));const ok=cam.isOrthographicCamera&&P.ortho;setProjection(false);return {ok,detail:'載入後 cam='+cam.type};});


// ---------- W. 記憶體釋放 ----------
T('W 記憶體釋放','按鈕開啟面板並顯示記憶體資訊',()=>{$('btnMem').click();const t=$('memPanel').textContent;const ok=$('memPanel').style.display==='block'&&t.includes('JS 記憶體')&&t.includes('復原歷史')&&t.includes('一鍵釋放');$('memPanel').style.display='none';return {ok,detail:t.replace(/\s+/g,' ').slice(0,80)};});
T('W 記憶體釋放','清除復原歷史：保留目前設計',()=>{reset();sync();for(let i=0;i<5;i++){P.width=100+i*5;lastPushT=0;sync();}const n=HIST.length;const w=P.width;const r=releaseHistory();return {ok:n>=3&&HIST.length===0&&REDO.length===0&&P.width===w&&r===n,detail:`清除 ${r} 筆，目前寬度仍 ${P.width}`};});
T('W 記憶體釋放','釋放暫存：縮放狀態與縮圖清空、設計不變',()=>{reset();sync();goStep(5);setView('flat');renderFlat();zoomAt(2,300,300);refreshSwatches(true);const n0=Object.keys(ZV).length,s0=$('swatches').children.length;const w=P.width;releaseCaches();return {ok:n0>0&&s0>0&&Object.keys(ZV).length===0&&$('swatches').children.length===0&&P.width===w,detail:`縮放狀態 ${n0}→0，縮圖 ${s0}→0`};});
T('W 記憶體釋放','暫時關閉貼皮預覽：貼皮網格釋放，但設計與匯出不受影響',()=>{reset();sync();SEL.clear();SEL.add(FACES[0].name);P.skinType='brick';applySkin(false);runSkins(curP);const a=skinGeoms.length;releaseSkinPreview();const b=skinGeoms.length,kept=Object.keys(P.skins).length>0;return {ok:a>0&&b===0&&kept&&P.skinPreviewOff,detail:`皮膚網格 ${a} → ${b}，貼皮設定保留=${kept}`};});
T('W 記憶體釋放','貼皮預覽關閉後，匯出路徑仍需要貼皮（need 判斷）',()=>{reset();sync();SEL.clear();SEL.add(FACES[0].name);P.skinType='brick';applySkin(false);releaseSkinPreview();const need=FACES.some(f=>skinLayersFor(f).length);return {ok:need&&skinGeoms.length===0,detail:'仍有貼皮層 '+need+'，預覽網格 '+skinGeoms.length+'（匯出時會重算）'};});
T('W 記憶體釋放','恢復貼皮預覽後重新產生',()=>{reset();sync();SEL.clear();SEL.add(FACES[0].name);P.skinType='brick';applySkin(false);releaseSkinPreview();restoreSkinPreview();runSkins(curP);return {ok:!P.skinPreviewOff&&skinGeoms.length>0,detail:'皮膚網格 '+skinGeoms.length};});
T('W 記憶體釋放','降低預覽解析度到 0.8mm（只影響預覽）',()=>{reset();P.skinRes='0.3';P.skinResOut='0.2';sync();const r=lowerPreviewRes();return {ok:r&&P.skinRes==='0.8'&&P.skinResOut==='0.2',detail:`預覽 ${P.skinRes}，輸出仍 ${P.skinResOut}`};});
T('W 記憶體釋放','一鍵釋放：歷史、快取、解析度一次處理並重新同步',()=>{reset();P.skinRes='0.3';sync();for(let i=0;i<4;i++){P.depth=100+i*5;lastPushT=0;sync();}$('btnMem').click();$('memAll').click();const ok=HIST.length===0&&P.skinRes==='0.8'&&$('memPanel').textContent.includes('已清除');$('memPanel').style.display='none';return {ok,detail:$('memPanel').textContent.slice(-40)};});
T('W 記憶體釋放','貼皮縮圖只在貼皮步驟產生（省記憶體）',()=>{reset();sync();$('swatches').innerHTML='';swSig='';goStep(2);sync();const a=$('swatches').children.length;goStep(4);sync();const b=$('swatches').children.length;return {ok:a===0&&b>20,detail:`步驟② ${a} 張、步驟④ ${b} 張`};});


// ---------- X. 分片列印與紋理薄片 ----------
const gbx=g=>{g.computeBoundingBox();return g.boundingBox;};
const skinned=()=>{reset();P.mode='3d';sync();SEL.clear();SEL.add(FACES[0].name);P.skinType='brick';applySkin(false);sync();};
T('X 分片與紋理','選項存在且預設關閉；按鈕依勾選顯示',()=>{reset();sync();const a=$('exportPanels').style.display==='none'&&$('exportTex').style.display==='none'&&P.splitPanels===false&&P.texPlate===false;goStep(6);P.splitPanels=true;P.texPlate=true;sync();const b=$('exportPanels').style.display!=='none'&&$('exportTex').style.display!=='none';P.splitPanels=false;P.texPlate=false;sync();return {ok:a&&b,detail:`預設隱藏=${a}，勾選後顯示=${b}`};});
T('X 分片與紋理','分片牆板：每片平放、底面在 z=0、厚度＝板厚',()=>{reset();P.panelT=2.4;sync();const {geoms,lay,t}=buildPanelSolids(curP,0);const ok=geoms.length===lay.items.length&&geoms.length>=5&&geoms.every(g=>{const b=gbx(g);return Math.abs(b.min.z)<1e-6&&Math.abs(b.max.z-2.4)<1e-6;});return {ok,detail:`${geoms.length} 片，板厚 ${t}`};});
T('X 分片與紋理','分片牆板：窗洞、燈孔以挖孔保留',()=>{reset();P.splitPanels=true;sync();const {lay}=panelLayoutFor(curP);const holes=lay.items.reduce((a,i)=>a+i.holes.length+i.circles.length,0);return {ok:holes>0,detail:'孔洞總數 '+holes};});
T('X 分片與紋理','分片牆板：拼版不超出列印平台寬度',()=>{reset();P.bedW=256;sync();const {lay}=panelLayoutFor(curP);return {ok:lay.W<=256+1e-6||lay.items.some(i=>i.w+10>256),detail:`拼版寬 ${lay.W.toFixed(0)}`};});
T('X 分片與紋理','分片牆板：板厚改變時零件厚度跟著變',()=>{reset();P.panelT=3.2;sync();const {geoms}=buildPanelSolids(curP,0);const b=gbx(geoms[0]);return {ok:Math.abs(b.max.z-3.2)<1e-6,detail:'厚 '+b.max.z.toFixed(2)};});
T('X 分片與紋理','分片牆板：未勾獨立紋理時，浮雕直接長在牆片上',()=>{skinned();P.texPlate=false;const a=buildPanelSolids(curP,0.5).geoms.length,b=a;const c=buildPanelSolids({...curP},0.5).geoms.length;const without=buildPanelSolids(curP,0).geoms.length;return {ok:c>without,detail:`含浮雕 ${c} 個網格 > 純牆板 ${without}`};});
T('X 分片與紋理','分片牆板：勾獨立紋理時牆片保持平整（不含浮雕）',()=>{skinned();P.texPlate=true;const n=buildPanelSolids(curP,0).geoms.length;const lay=panelLayoutFor(curP).lay.items.length;P.texPlate=false;return {ok:n===lay,detail:`牆片 ${lay}，網格 ${n}`};});
T('X 分片與紋理','紋理薄片：每個貼皮面一片、底板厚度正確、平放在 z≥0',()=>{skinned();const {plates}=buildTexPlates(curP,0.5,0.8);const ok=plates.length>=1&&plates.every(p=>{const b=gbx(p.g);return b.min.z>=-1e-6&&b.min.z<0.81&&b.max.z>0.8;});return {ok,detail:`${plates.length} 片`};});
T('X 分片與紋理','紋理薄片：底板厚度改變時薄片底面跟著變',()=>{skinned();const a=buildTexPlates(curP,0.5,0.8).plates[0],b=buildTexPlates(curP,0.5,1.6).plates[0];const ba=gbx(a.g),bb=gbx(b.g);return {ok:bb.max.z>ba.max.z+0.5,detail:`頂 ${ba.max.z.toFixed(2)} → ${bb.max.z.toFixed(2)}`};});
T('X 分片與紋理','紋理薄片：沒有貼皮時不產生薄片',()=>{reset();sync();return {ok:buildTexPlates(curP,0.5,0.8).plates.length===0,detail:'0 片'};});
T('X 分片與紋理','紋理薄片：避開窗洞（窗位置不長浮雕）',()=>{skinned();const g=FACES[0];const withWin=buildTexPlates(curP,0.5,0.8).plates.reduce((a,p)=>a+p.g.attributes.position.count,0);const p2={...curP,wins:[],winRows:0};let no=0;try{no=buildTexPlates(p2,0.5,0.8).plates.reduce((a,p)=>a+p.g.attributes.position.count,0);}catch(e){no=withWin;}return {ok:withWin>0&&withWin<=no,detail:`有窗 ${withWin} 頂點 ≤ 無窗 ${no}`};});
T('X 分片與紋理','紋理薄片：拼版寬度不超過列印平台',()=>{skinned();P.bedW=256;const r=buildTexPlates(curP,0.6,0.8);return {ok:r.plates.length>0&&r.W===256,detail:`拼版 ${r.W}×${r.H.toFixed(0)}`};});
T('X 分片與紋理','整體 STL：勾獨立紋理後不再把浮雕黏在本體上',()=>{skinned();P.texPlate=true;sync();const s=P.mode==='plate'||P.texPlate;P.texPlate=false;return {ok:s===true,detail:'texPlate 時略過本體貼皮'};});
T('X 分片與紋理','STL 輸出為有效二進位（三角形數與檔長相符）',()=>{reset();sync();const {geoms}=buildPanelSolids(curP,0);const dv=stlFlat(geoms),n=new DataView(dv.buffer||dv).getUint32(80,true),len=(dv.byteLength!==undefined?dv.byteLength:dv.length);return {ok:n>100&&len===84+n*50,detail:`${n} 三角形，${len} bytes`};});
T('X 分片與紋理','列印檢查顯示分片／薄片資訊',()=>{skinned();P.splitPanels=true;P.texPlate=true;goStep(6);sync();const t=document.body.innerText;P.splitPanels=false;P.texPlate=false;sync();return {ok:t.includes('分片列印')&&t.includes('紋理薄片'),detail:'檢查區含兩項說明'};});
T('X 分片與紋理','步驟⑥ 勾分片時預設顯示平面拼版',()=>{reset();P.splitPanels=true;goStep(6);sync();const v=defaultView();P.splitPanels=false;return {ok:v==='flat',detail:'預設視圖 '+v};});


// ---------- Y. 多扇門 ----------
const doorsOf=()=>windowList(curP).filter(w=>w.main);
T('Y 多扇門','預設仍是單扇門（相容舊行為）',()=>{reset();P.doorOn=true;sync();return {ok:doorsOf().length===1&&P.doorN===1,detail:'門數 '+doorsOf().length};});
T('Y 多扇門','同牆並排 3 扇：間距＝門寬＋間距',()=>{reset();P.doorOn=true;P.width=160;P.doorW=14;P.doorGap=4;P.doorN=3;P.doorC=-20;sync();const d=doorsOf();return {ok:d.length===3&&Math.abs(d[1].c-d[0].c-18)<1e-6&&Math.abs(d[2].c-d[1].c-18)<1e-6,detail:'位置 '+d.map(x=>x.c).join(',')};});
T('Y 多扇門','向左排：位置往負方向',()=>{reset();P.doorOn=true;P.width=160;P.doorN=2;P.doorDir='left';P.doorC=20;sync();const d=doorsOf();return {ok:d.length===2&&d[1].c<d[0].c,detail:d.map(x=>x.c).join(',')};});
T('Y 多扇門','超出牆面範圍的門自動略過',()=>{reset();P.doorOn=true;P.width=60;P.doorW=14;P.doorN=4;P.doorC=0;sync();const d=doorsOf();return {ok:d.length<4&&d.every(x=>Math.abs(x.c)<=(60-2*curP.wall-14)/2),detail:'實際 '+d.length+' 扇'};});
T('Y 多扇門','其他牆各加一扇：置中、各在該牆',()=>{reset();P.doorOn=true;P.doorWall='front';P.doorBack=true;P.doorLeft=true;P.doorRight=true;sync();const d=doorsOf(),w=d.map(x=>x.wall).sort().join();return {ok:d.length===4&&w==='back,front,left,right'&&d.filter(x=>x.extra).every(x=>x.c===0),detail:w};});
T('Y 多扇門','主門牆自己的勾選不會重複加門',()=>{reset();P.doorOn=true;P.doorWall='front';P.doorFront=true;sync();return {ok:doorsOf().length===1,detail:'門數 '+doorsOf().length};});
T('Y 多扇門','門的位置不會有窗戶重疊（自動讓位）',()=>{reset();P.doorOn=true;P.doorN=3;P.doorC=0;P.nFront=4;sync();const d=doorsOf().filter(x=>x.wall==='front'),ws=windowList(curP).filter(w=>!w.main&&w.wall==='front'&&w.y0<18);return {ok:ws.every(w=>d.every(x=>Math.abs(w.c-x.c)>=(w.w+x.w)/2+2-1e-6)),detail:'同牆低窗 '+ws.length};});
T('Y 多扇門','3D 開口：多扇門都實際切出（本體體積隨門數下降）',()=>{reset();P.doorOn=true;P.doorN=1;sync();const v1=vol(cur.g);P.doorN=3;P.width=160;sync();P.doorN=1;sync();const a=vol(cur.g);P.doorN=3;sync();const b=vol(cur.g);return {ok:b<a-1,detail:`體積 ${a.toFixed(0)} → ${b.toFixed(0)}`};});
T('Y 多扇門','立面圖與平面圖會顯示所有門',()=>{reset();P.doorOn=true;P.doorN=3;P.width=160;P.doorBack=true;sync();goStep(3);setView('flat');renderFlat();const e=$('flat').innerHTML;goStep(5);setView('flat');renderFlat();const pl=$('flat').innerHTML;return {ok:(e.match(/#8bc34a/g)||[]).length>=3,detail:'立面綠色門面 '+(e.match(/#8bc34a/g)||[]).length};});
T('Y 多扇門','存檔載入保留多門設定',()=>{reset();P.doorOn=true;P.doorN=3;P.doorBack=true;const j=JSON.stringify(P);applyState(JSON.parse(j));return {ok:P.doorN===3&&P.doorBack===true,detail:`doorN=${P.doorN}`};});


// ---------- Z. 窗戶本體、門板款式、屋頂紋路解析度 ----------
const exN=()=>extraGeoms.length;
const baseDoor=()=>{reset();P.doorOn=true;P.doorW=16;P.doorH=20;P.wallH=30;P.floorH=30;sync();};
const gbb=g=>{g.computeBoundingBox();return g.boundingBox;};
T('Z 零件選項','預設不產生窗戶本體與門板（牆體開口維持原樣）',()=>{baseDoor();P.nFront=2;sync();return {ok:buildWinBodies(curP).length===0&&buildDoorLeaves(curP).length===0,detail:'0 / 0'};});
T('Z 零件選項','窗戶玻璃片：每扇窗一片，位於牆厚中間、不凸出外牆',()=>{reset();P.nFront=2;P.winGlass=true;sync();const g=buildWinBodies(curP),n=windowList(curP).filter(w=>!w.main).length;const zmax=Math.max(...g.map(x=>gbb(x).max.z));return {ok:g.length===n&&zmax<=curP.depth/2+1e-6,detail:`玻璃 ${g.length}／窗 ${n}，最外 z=${zmax.toFixed(2)}`};});
T('Z 零件選項','窗格條：十字窗比固定窗多出零件',()=>{reset();P.nFront=1;P.nBack=0;P.nLeft=0;P.nRight=0;P.winBars=true;P.winStyle='fixed';sync();const a=buildWinBodies(curP).length;P.winStyle='cross';sync();const b=buildWinBodies(curP).length;return {ok:b>a,detail:`固定 ${a} → 十字 ${b}`};});
T('Z 零件選項','窗戶本體不改牆：牆體體積與勾選前相同',()=>{reset();P.nFront=2;sync();const a=vol(cur.g);P.winGlass=true;P.winBars=true;sync();const b=vol(cur.g);return {ok:Math.abs(a-b)<1e-6,detail:`${a.toFixed(0)} = ${b.toFixed(0)}`};});
T('Z 零件選項','窗戶本體進入輸出零件（extraGeoms 增加）',()=>{reset();P.nFront=2;sync();const a=exN();P.winGlass=true;sync();return {ok:exN()>a,detail:`${a} → ${exN()}`};});
T('Z 零件選項','門板：七種款式皆可產生、零件數量合理',()=>{baseDoor();P.doorLeaf=true;const r={};for(const t of Object.keys(DOORTYPES)){P.doorType=t;P.doorHandle='none';sync();r[t]=buildDoorLeaves(curP).length;}return {ok:Object.values(r).every(n=>n>=1),detail:JSON.stringify(r)};});
T('Z 零件選項','門板：木門有嵌板、平板門只有一片',()=>{baseDoor();P.doorLeaf=true;P.doorHandle='none';P.doorType='plain';sync();const a=buildDoorLeaves(curP).length;P.doorType='wood';sync();const b=buildDoorLeaves(curP).length;return {ok:a===1&&b>3,detail:`平板 ${a}、木門 ${b}`};});
T('Z 零件選項','門把：喇叭鎖／把手鎖／直把／無',()=>{baseDoor();P.doorLeaf=true;P.doorType='wood';const r={};for(const h of Object.keys(DOORHANDLES)){P.doorHandle=h;sync();r[h]=buildDoorLeaves(curP).length;}return {ok:r.none<r.trumpet&&r.none<r.lever&&r.none<r.bar,detail:JSON.stringify(r)};});
T('Z 零件選項','鐵捲門與分節式車庫門不加門把',()=>{baseDoor();P.doorLeaf=true;P.doorHandle='trumpet';P.doorType='wood';sync();const w=buildDoorLeaves(curP).length;P.doorType='roller';sync();const a=buildDoorLeaves(curP);P.doorType='sectional';sync();const b=buildDoorLeaves(curP);return {ok:a.length>3&&b.length>3,detail:`鐵捲門 ${a.length}、分節 ${b.length}`};});
T('Z 零件選項','雙開門：兩片門板各一組門把',()=>{baseDoor();P.doorLeaf=true;P.doorType='plain';P.doorHandle='trumpet';P.doorStyle='double';sync();const d=buildDoorLeaves(curP).length;P.doorStyle='single';sync();const s1=buildDoorLeaves(curP).length;return {ok:d>s1,detail:`雙開 ${d}、單扇 ${s1}`};});
T('Z 零件選項','門板位於門洞範圍內，且不凸出牆面超過 4mm（含門把）',()=>{baseDoor();P.doorLeaf=true;P.doorType='wood';P.doorHandle='trumpet';sync();const g=buildDoorLeaves(curP),D=curP.depth/2;let zmax=-999,zmin=999;for(const x of g){const b=gbb(x);zmax=Math.max(zmax,b.max.z);zmin=Math.min(zmin,b.min.z);}return {ok:zmax<=D+4&&zmin>=D-curP.wall-0.01,detail:`z ${zmin.toFixed(2)}~${zmax.toFixed(2)}（牆面 ${D}）`};});
T('Z 零件選項','側牆的門板方向正確（左右牆）',()=>{baseDoor();P.doorLeaf=true;P.doorType='plain';P.doorHandle='none';P.doorWall='right';sync();const b1=gbb(buildDoorLeaves(curP)[0]);const W=curP.width/2;P.doorWall='left';sync();const b2=gbb(buildDoorLeaves(curP)[0]);return {ok:b1.max.x<=W+0.01&&b1.min.x>=W-curP.wall-0.01&&b2.min.x>=-W-0.01&&b2.max.x<=-W+curP.wall+0.01,detail:`右牆 x ${b1.min.x.toFixed(1)}~${b1.max.x.toFixed(1)}；左牆 x ${b2.min.x.toFixed(1)}~${b2.max.x.toFixed(1)}`};});
T('Z 零件選項','多扇門／其他牆的門都有門板',()=>{baseDoor();P.width=160;P.doorLeaf=true;P.doorType='plain';P.doorHandle='none';P.doorN=2;P.doorBack=true;sync();return {ok:buildDoorLeaves(curP).length===3,detail:'門板 '+buildDoorLeaves(curP).length};});
T('Z 零件選項','門板不改牆：牆體體積不變',()=>{baseDoor();const a=vol(cur.g);P.doorLeaf=true;sync();return {ok:Math.abs(a-vol(cur.g))<1e-6,detail:'體積相同'};});
T('Z 零件選項','選項顯示：未勾門板時隱藏款式與門把',()=>{baseDoor();P.doorLeaf=false;goStep(3);sync();const el=k=>document.querySelector('#panel [data-k="'+k+'"]').style.display;const a=el('doorType')==='none'&&el('doorHandle')==='none';P.doorLeaf=true;sync();const b=el('doorType')!=='none';return {ok:a&&b,detail:`隱藏=${a}，顯示=${b}`};});
T('Z 零件選項','屋頂步驟出現預覽／輸出解析度，且與貼皮步驟共用同一數值',()=>{reset();P.roofStyle='clay';goStep(2);sync();const els=[...document.querySelectorAll('#panel [data-rr="1"]')];const vis=els.length===2&&els.every(e=>e.style.display!=='none');P.roofStyle='none';sync();const hid=els.every(e=>e.style.display==='none');return {ok:vis&&hid,detail:`有款式時顯示=${vis}，無款式隱藏=${hid}`};});
T('Z 零件選項','屋頂解析度改變 → 屋頂紋路三角面數改變',()=>{reset();P.roofStyle='clay';P.skinRes='0.8';sync();runSkins(curP);const a=skinGeoms.filter(g=>g.userData.roof).reduce((s,g)=>s+g.attributes.position.count,0);P.skinRes='0.5';sync();runSkins(curP);const b=skinGeoms.filter(g=>g.userData.roof).reduce((s,g)=>s+g.attributes.position.count,0);return {ok:a>0&&b>a*1.5,detail:`0.8mm ${a/3|0} → 0.5mm ${b/3|0} 三角面`};});
T('Z 零件選項','屋頂步驟顯示屋頂紋路面數資訊',()=>{reset();P.roofStyle='clay';goStep(2);sync();runSkins(curP);return {ok:$('roofInfo').textContent.includes('三角面'),detail:$('roofInfo').textContent.slice(0,40)};});
T('Z 零件選項','存檔載入保留窗戶本體與門板設定',()=>{baseDoor();P.doorLeaf=true;P.doorType='grille';P.doorHandle='lever';P.winGlass=true;const j=JSON.stringify(P);applyState(JSON.parse(j));return {ok:P.doorType==='grille'&&P.doorHandle==='lever'&&P.winGlass===true,detail:P.doorType};});

// ---------- 蒐集 STEP 測試狀態 ----------
T('J 蒐集 STEP 測試','產生 9 組 STEP 輸入',()=>{
 reset();sync();snapStep();
 reset();P.floors=2;P.slabOn=true;P.roofSplit=true;P.frameOn=true;P.ridgeCap=true;P.chimOn=true;P.eaveX=8;P.eaveZ=8;P.iwalls=[newIwall('x'),newIwall('z')];sync();snapStep();
 reset();P.roof='hip';P.width=120;P.depth=90;P.lampShape='hex';P.lampLayout='honey';P.lampN=4;P.lampRows=3;P.lampD=9;sync();snapStep();
 reset();P.roof='mansard';P.rise=30;P.floors=2;P.winStyle='arch';sync();snapStep();
 reset();P.roof='gambrel';P.lampTarget='roof';P.roofSplit=true;sync();snapStep();
 reset();P.roof='hip';P.floors=3;P.slabOn=true;P.doorOn=true;P.doorStyle='arch';sync();ensureStairs();P.stairs[0].on=true;P.stairs[1].on=true;P.stairs[1].x=20;P.stairs[1].dir='-z';sync();snapStep();
 reset();P.annex=[newAnnex('garage',{side:'right',off:-10}),newAnnex('porch',{side:'front',off:-18}),newAnnex('shed',{side:'back',gap:10})];sync();snapStep();
 reset();P.floors=2;P.slabOn=true;P.floorOn=true;P.iwalls=[{axis:'x',floor:0,pos:0,a0:-30,a1:30,doors:[{c:0,w:10,h:15}]},{axis:'z',floor:1,pos:5,a0:-30,a1:30,doors:[{c:0,w:10,h:15}]}];sync();snapStep();
 reset();P.floors=3;P.slabOn=true;P.floorOn=true;sync();ensureStairs();Object.assign(P.stairs[0],{on:true,type:'L',x:-35,z:-30,struct:'open',rail:'both'});Object.assign(P.stairs[1],{on:true,type:'U',chain:true,chainTurn:'straight',rail:'right'});sync();snapStep();
 return {ok:window.__STEPS.length===9,detail:'組數 '+window.__STEPS.length};});

setTimeout(()=>{const pre=document.createElement('pre');pre.id='RESULT';pre.textContent=JSON.stringify({results:R,steps:window.__STEPS});document.body.appendChild(pre);},3500);
